const PWD_MAXLEN = 200;
// 外部可控整数参数的统一钳制：NaN / 负数 / 天文数字一律落回合法区间内的默认值。
// 路由里那些 `Number(b.n) || 30` 看着有兜底，其实只挡了 NaN 与 0 ——
// 负数照样穿过去（slice(0, -5) 与"取前 5 名"是两回事），1e9 也照样穿过去。
function _clampInt(v, lo, hi, dflt) {
  const n = Number(v);
  if (!Number.isFinite(n)) return dflt;
  return Math.max(lo, Math.min(hi, Math.round(n)));
}
