const isDistortDay = () => { const b = todayBreadth(); return !!(b && b.distort); };
const _cl = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
// 条件自动优化用的一句话体检：让"今天到底能不能按正常标准判断"有据可依
function marketHealthNote() {
  const b = todayBreadth();
  if (!b) return '';
  // ⛔ 这份数属于哪天必须说清楚（da 轮）：休市日/开盘前拿到的是上一交易日收盘的快照，
  //    不加日期就说"市场结构失真"，等于拿几天前的结论当今天的话讲。
  const _dd = b.isToday === false ? `（截至 ${String(b.basisDay || '').slice(4, 6)}/${String(b.basisDay || '').slice(6, 8)} 收盘）` : '';
  if (b.distort) return `\n⚠️ 市场结构失真${_dd}：${b.note}（自动优化已按结构市处理，不拿命中率罚模型）`;
  return '';
}

// ---------------- 样本统计口径：日等权 + 大盘 beta 中性化 ----------------
// 2026-09-28 事故复盘（用户一句「优化错了」点破，事后查 stats.json 拿到三条铁证）：
//   ① 单日灌爆：9/28 一天进了 1373 条样本 = 全部样本的 70%，一天把两个月历史淹没；
//   ② 重复登记：1973 条里 1007 条是「同类型+同代码+同日期」重复（占 51%）；
//   ③ n=1 天下结论：12 个技术条件 + 90+/85-89/80-84 三个概率桶，样本**全部只覆盖 1 个交易日**。
//   且这天恰是系统性大跌（上证 -1.67 / 深证 -3.44 / 创业板 -4.53）。
//   → 所有"降权结论"都是拿单个普跌日算出来的，本质是拿市场 beta 当选股 alpha 惩罚。
// 修法三件套：
//   ① 日等权：每天内部先算一次命中率再跨天平均，任何单日最多占 1/N 权重，灌不爆；
//   ② beta 中性化：每天的期望命中率按当日指数涨跌换算，把"市场给不给机会"剥掉；
//   ③ 交易日数门槛：覆盖不足 MIN_LEARN_DAYS 个交易日，一律不校准、不降权、不抬门槛。
const MIN_LEARN_DAYS = 5;   // 少于 5 个交易日的证据，统计学上等于没证据

// 日等权统计（核心工具）：days=独立交易日数，dayRate=每天各算一次再平均
function dayStats(list) {
  const byDay = {};
  for (const s of list) {
    const d = normDate(s.date);
    if (!byDay[d]) byDay[d] = { n: 0, hit: 0 };
    // ⛔ 预测力口径（cy 轮）：跨度与命中都只认 nd，否则"跨了几个交易日"与"命中率"
    //    用的是两套数（一个按当天、一个按次日），日均值就是混出来的
    byDay[d].n++; if (s.type === 'auczt' ? !!(s.resolved && s.resolved.limitUp) : !!(s.nd && s.nd.hit)) byDay[d].hit++;
  }
  const days = Object.keys(byDay);
  if (!days.length) return { days: 0, n: 0, hit: 0, dayRate: 0, byDay: {} };
  let n = 0, hit = 0, acc = 0;
  for (const d of days) { n += byDay[d].n; hit += byDay[d].hit; acc += byDay[d].hit / byDay[d].n; }
  return { days: days.length, n, hit, dayRate: acc / days.length, byDay };
}
// 每日「期望命中率」基准表。有指数数据优先用指数（客观），否则用当日整体表现做 beta 代理，
//   样本少的天向全局收缩，避免把噪声当天赋差异。
function dayExpectMap(res, globalBase) {
  const st = dayStats(res), map = {};
  for (const [d, v] of Object.entries(st.byDay)) {
    const idx = S.marketBeta[d];
    const proxy = v.hit / v.n;
    const w = Math.min(1, v.n / 20);
    const smoothed = proxy * w + globalBase * (1 - w);
    // 指数换算：大盘跌 3% → 期望约 26%；涨 1% → 58%（上证/深证/创业板涨跌幅均值）
    map[d] = Number.isFinite(idx)
      ? _cl(_cl(0.5 + idx * 0.08, 0.18, 0.75) * 0.6 + smoothed * 0.4, 0.18, 0.75)
      : _cl(smoothed, 0.18, 0.75);
  }
  return map;
}
// 把一批样本的命中率做 beta 中性化：它所在的那些日子本身可能是普跌/普涨日，
//   先把这些因素除掉，剩下的才是模型自身的水平。返回 null 表示无法判定。
function neutralRate(list, expMap, globalBase) {
  const st = dayStats(list);
  if (!st.days || !st.n) return null;
  let own = 0;
  for (const [d, v] of Object.entries(st.byDay)) own += v.n * (Number.isFinite(expMap[d]) ? expMap[d] : globalBase);
  const ownBase = own / st.n;
  if (!(ownBase > 0)) return null;
  return _cl((st.hit / st.n) * (globalBase / ownBase), 0, 1);
}
// 是否由普跌日样本主导（这类日子绝对命中率天然低，只加权不降权）
function bearDominated(list) {
  let tot = 0, bear = 0;
  for (const s of list) {
    const b = S.marketBeta[normDate(s.date)];
    if (!Number.isFinite(b)) continue;
    tot++; if (b < -1) bear++;
  }
  return tot >= 5 && bear / tot >= 0.5;
}
// 全局学习上下文：以「全部已回验样本」为基准，供任意子集做相对比较
function learnCtx(all) {
  // ⛔⛔ B1 轮（2026-10-17）：beta 中性化的市场基准只认【次日命中】口径的样本。
  //    auczt 预测的是【当日封板】（hx 口径例外，实测当日封板率 ~12%），其余类型预测次日
  //    命中（~30%）—— 两种目标混在一起算"市场基准"，基准本身是混的，中性化越中性越歪。
  //    两个调用方（trendSelfOptimize / recomputeBuckets）判的都是次日口径池，基准不含 auczt。
  const ndPool = (all || []).filter(s => s.type !== 'auczt');
  const g = dayStats(ndPool);
  const GLOBAL = g.days ? _cl(g.dayRate, 0.2, 0.8) : 0.5;
  return { GLOBAL, EXP: dayExpectMap(ndPool, GLOBAL), days: g.days, n: g.n };
}

function logSignal(type, code, name, price, prob, extra = {}) {
  // 周末/非交易日登记的样本无法回验（没有对应的交易日K线可比对），
  // 以前照样登记 → 越堆越多却永远回验不了，还会把命中率统计稀释成假数据。这里直接标废。
  // ⛔ 2026-10-06 补：原来只判 `wd===0||wd===6`，法定假日里的周三照样登记进样本库，
  //    同样永远回验不了（休市日没有次日K线），却一样参与命中率分母 —— 与上面那段注释
  //    想解决的问题是同一个，只是漏了节假日那一半。统一走 isTradeDay。
  const _nd = new Date();
  // 概率一律按「百分数」登记（68 = 68%）。学习库按 ≥90/85/80/70 分桶，
  //   若误传 0~1 小数会被当成 0%~1% 落进 <70 桶，把校准系数算歪 —— 这里直接判为无效值。
  const _p = (prob == null || !(prob > 1)) ? null : +(+prob).toFixed(0);
  // ⚠️ 重复登记修正（2026-09-29 发现）：同一只票同一天的同类信号以前会登记多次
  //    （实测 1973 条样本里有 1007 条是重复的，占 51%，例如 zt|600418|20260928 记了 3 次）。
  //    少数反复触发的票会重复计分，把整体命中率从真实的 43% 压到 30%。
  //    统计仍每类/股/日只计一次；首次输入不覆写，后来观察另行追加不可变证据。
  const _key = type + '|' + code + '|' + todayStr();
  // ── 学习融合值：登记时就把它算出来存进样本 ──
  //   以前样本里只有"模型原值"，回验后只能评估模型准不准，永远无法回答
  //   「学完之后是不是更准」。现在并存一个 fused，回验时两套分档一起统计，
  //   learnFusedReport() 直接给出"融合档命中率 − 原值档命中率"= 学习带来的增量。
  const _rows = krowsOf(code);
  const _fz = fusedProb(code, name, _rows, type, _p);
  const _old = S.learn.signals.find(s => s.type === type && s.code === code && s.date === todayStr());
  const observation=captureProductionSignal({ts:Date.now(),type,code,name,price,prob:_p,
    probKind:probKindOf(type)==='score'?'score':'model-estimate',eventTarget:_fz.target!==undefined?_fz.target:'unknown',_fz,
    strategyVersion:extra.strategyVersion||productionSignalVersion(),conditionEvidence:extra.conditionEvidence||[],conditionCoverage:extra.conditionCoverage,governanceEvidence:extra.governanceEvidence,
    logic:(extra.paths||[]).join('；'),risk:extra.signalRisk||'',stopLoss:extra.stopLoss||'',invalidWhen:extra.invalidWhen||''},
    extra.quoteEvidence||{price},_rows,{recordKind:'observation',supersedes:_old?.signalId||null,
      metrics:{originalRecord:extra.sourceRecord||null,cal:extra.cal??null,score:extra.score??null,legacyParent:_old&&!_old.signalId?{type:_old.type,code:_old.code,date:_old.date,ts:_old.ts??null}:null}});
  const result={..._fz,signalId:observation.signalId,evidenceFingerprint:observation.evidenceFingerprint,evidenceArchiveStatus:observation.evidenceArchiveStatus};
  if (_old) return result;
  const sampleExtra={...extra};
  delete sampleExtra.quoteEvidence; delete sampleExtra.conditionEvidence; delete sampleExtra.conditionCoverage; delete sampleExtra.governanceEvidence; delete sampleExtra.sourceRecord;
  S.learn.signals.push({
    ...JSON.parse(JSON.stringify(sampleExtra)),
    date: todayStr(), ts: observation.ts, type, code, name, price,
    prob: _p, probKind: probKindOf(type),
    fused: _fz.prob, laP: _fz.la, empP: _fz.emp, delta: _fz.delta,
    void: !isTradeDay(_nd),
    signalId:observation.signalId,evidenceFingerprint:observation.evidenceFingerprint,
    evidenceArchiveStatus:observation.evidenceArchiveStatus,strategyVersion:observation.strategyVersion
  });
  // ⚠️ 剪枝口径已改（原 string）：以前直接 slice(-1500) 丢最老的，配合"9/28 一天 1373 条"
  //    两天就能把 7~9 月的历史样本清空 → 学习库只剩两三天 → 又回到「拿一天下结论」的死循环。
  //    现在按「交易日配额」剪：每天最多留 quota 条，保住日期多样性。
  pruneSignals();
  saveLearn();
  return result;
}
// 样本库剪枝：体积要控，但「独立交易日数」更要保住 —— 它是所有学习结论的证据厚度。
function pruneSignals(limit = 2600) {
  const arr = S.learn.signals;
  // ⛔ 返回值契约（2026-11-02 nf 轮，2026-11-03 复原）：未超限也要交出结构，调用方/守门才能统一读
  if (arr.length <= limit) return { total: arr.length, dropped: 0, droppedByType: {} };
  const byDay = {};
  for (const s of arr) { const d = normDate(s.date); (byDay[d] = byDay[d] || []).push(s); }
  const days = Object.keys(byDay).sort();
  // ⛔ 2026-10-07 修（本轮角度：系统里"只增不减"的东西 —— 清理判据自身要自洽）：
  //    原写法 `quota = Math.max(30, floor(limit/days))` 里的【每天至少 30 条】与【总量 limit】是两个
  //    互相打架的目标：交易日一多，`30 × 天数` 必然撑破总量上限（days>86 时即如此），
  //    于是最后那句 `slice(-limit)` 一刀切丢掉最早的若干天 —— 退化成「只留最近 86 天」，
  //    与这段剪枝"保住独立交易日数（证据厚度）"的初衷**正好相反**，而且从那天起每天都在稳定吃掉最早一天。
  //    实测：当前库已覆盖 68 个交易日（最早 2026-07-07），距离触发只剩约 19 个交易日。
  //    现在改成两步：① 按天均分（保证总量不超）② 没用完的额度按天再补 —— 每天都留一点，绝不整体丢天。
  const base = Math.max(1, Math.floor(limit / Math.max(days.length, 1)));
  const take = new Map();
  let used = 0;
  for (const d of days) { const n = Math.min(base, byDay[d].length); take.set(d, n); used += n; }
  let extra = limit - used;
  while (extra > 0) {                       // 富余额度再分一轮（天与天之间轮流加，保持均匀）
    let moved = 0;
    for (const d of days) {
      if (extra <= 0) break;
      const cur = take.get(d) || 0;
      if (cur < byDay[d].length) { take.set(d, cur + 1); extra--; moved++; }
    }
    if (!moved) break;
  }
  // 极端情况（交易日数本身就超过总量上限）：每天 1 条仍放不下，只能保留最近的若干天。
  // ⛔ 这时必须说出来 —— 静默丢掉历史样本会让学习结论悄悄退回"拿最近几天下结论"。
  let keepDays = days;
  if (used > limit) {
    const room = Math.max(1, Math.floor(limit / 1));
    keepDays = days.slice(Math.max(0, days.length - room));
    console.warn(`[learn] ⚠️ 交易日数(${days.length})已超过样本上限(${limit})，每天 1 条也放不下 —— 只能保留最近 ${keepDays.length} 个交易日，更早的样本将被丢弃`);
  }
  // ⛔ nf 轮（2026-11-02 每日回测，2026-11-03 复原）：当日保留顺序 = 【当日稀有类型优先】→【已回验优先】→【登记先后】。
  //    原写法只按 resolved 排序，而当天刚登记的信号 resolved=false → 排在当日队尾，
  //    slice(0, cap) 先把它们砍掉；而一进二 / 连板接力恰好是当日**最后**登记的（15:30 收盘后推送时写），
  //    于是每天都走一遍「推了 → 样本被自己的登记动作删掉 → 永远回验不了」。
  //    实测：10-27/10-28/10-29 三天一进二真推了（pushlog ✅），stats.json 里这三天 yier/lianban = 0 条；yier 样本 21→17→11 一路掉。
  //    改成类型稀有度优先：每天几条的 yier/lianban 先留，砍掉的名额从最富裕的类型（aucres/auczt）里出。
  const keep = [];
  for (const d of keepDays) {
    const tcnt = {};
    for (const s of byDay[d]) tcnt[s.type] = (tcnt[s.type] || 0) + 1;
    const list = byDay[d].slice().sort((a, b) =>
      ((tcnt[a.type] || 0) - (tcnt[b.type] || 0)) ||              // ① 当日稀有类型先留
      ((b.resolved ? 1 : 0) - (a.resolved ? 1 : 0)) ||            // ② 已回验的优先留（有证据价值）
      ((a.ts || 0) - (b.ts || 0)));                               // ③ 同档按登记先后（确定性）
    keep.push(...list.slice(0, take.get(d) || base));
  }
  let out = keep.sort((a, b) => (a.ts || 0) - (b.ts || 0));
  if (out.length > limit) out = out.slice(out.length - limit);
  const dropped = arr.length - out.length;
  const keptDays = new Set(out.map(s => normDate(s.date))).size;
  S.learn.signals = out;
  // 剪枝报告：不只说“剪了几条”，还要说清“剪的是哪类”——否则稀有类型被整类清空也看不出来。
  const keptRef = new Set(out);
  const droppedByType = {};
  for (const s of arr) {
    if (keptRef.has(s)) continue;
    const k = s.type || '?';
    droppedByType[k] = (droppedByType[k] || 0) + 1;
  }
  const _dtxt = Object.keys(droppedByType).sort((a, b) => droppedByType[b] - droppedByType[a]).map(k => k + ' -' + droppedByType[k]).join(' / ');
  if (dropped > 0) console.log(`[learn] 样本库超限，按交易日配额(约${Math.round(out.length / Math.max(keptDays, 1))}/天)剪枝 ${dropped} 条，保留 ${out.length} 条 / ${keptDays} 个交易日（原有 ${days.length} 个交易日）；按类型：${_dtxt}`);
  return { total: out.length, dropped, droppedByType };
}
// ⚠️ 原「概率量纲清洗 + 学习口径升级」两块已下移到 S.config 初始化之后
//   （见下方【启动期学习数据治理】）—— 因为 recomputeBuckets 内部会读写 S.config，
//   放在这个位置会因 S.config 尚未初始化而抛错并被 catch 静默吞掉，等于没跑。

// ⚠️⚠️ 这里修掉了一个让「自学习」完全失效的隐藏 bug（2026-09-27 发现）：
//   logSignal 登记的日期是 todayStr() = '20260927'（无连字符），
//   而 K 线里的日期是 '2026-09-27'（带连字符）—— 两者 findIndex 精确比较永远不相等，
//   结果 287 条信号「已登记、0 回验」，buckets 全空、样本数 0，
//   也就是说：概率校准/阈值自适应/涨停率统计这些"学习"其实一天都没有真正跑起来过。
//   更隐蔽的是它不报错、不告警，面板看上去一切正常。现在统一日期格式再比较。
function normDate(d) {
  const s = String(d == null ? '' : d).replace(/[^0-9]/g, '');
  if (s.length !== 8) return String(d == null ? '' : d);
  return s.slice(0, 4) + '-' + s.slice(4, 6) + '-' + s.slice(6, 8);
}
// 用K线回验单条信号（返回是否新回验成功）
// 口径：优先用【信号当日】那根K线（收盘后才回验，避免盘中拿到残缺的当日bar误判），
//       当日没有bar（周末/非交易日登记的信号）则退化为【之后的第一根】K线。
//       命中 = 从登记价到该K线最高价 ≥HIT_THR%；强命中 = 期间涨停。
// ⚠️ 命中口径是全局常量（2026-09-29 用户指定 5% → 3%）：判定、文案、存量重算全部引用它，
//    以后再改口径只动这一个数字 —— 切勿在别处再写死 5 或 3。
const HIT_THR = 3;

// ── 概率是一句「结论」，它赌的是哪件事必须由它自己说清楚（2026-10-08 dd 轮）──────────
// ⛔ 系统里同一个词在不同模块指的**不是同一件事**，而文案一律只写一个百分数：
//      · 「涨停概率」在盘中模块（大单 / 后排蓄势 / 竞价推断）赌的是【当日】封板，
//        在板块异动 / 复盘 / 涨停前形态赌的是【次日】封板（都出自 A.nextDayLimitProb）；
//      · 「上涨概率 / 胜率 / 命中率」的回验口径是【次日最高涨幅≥HIT_THR%】（sig.nd）。
//    用户看到一屏百分数，却不知道系统到底在赌哪件事 —— 结论给了、前提没给。
//    现在由这一张表统一给每个百分数补上事件定义；**口径改了只动这一处**。
// ⛔ kind 认不出来就返回空串 —— 宁可不说，也绝不许给一个没核实过的定义。
const PROB_DEF = {
  ztToday: '当日封板',
  ztNext: '次日封板',
  up3Next: `次日最高涨≥${HIT_THR}%`,
};
function probDef(kind) { return PROB_DEF[kind] || ''; }
function probTag(kind, v) {
  const d = PROB_DEF[kind];
  // 数值本身是 '-' / null 时连定义一起省掉：没给数就别描述赌的是什么
  if (!d || v == null || v === '-') return '';
  return `（${d}）`;
}
// 信号类型 → 概率事件定义（给 fuseLine 的「学后胜率」补前提用；查不到就不补）
// ⛔ 判定规则（改这条规则 = 全部文案跟着变，别在各处单独写）：
//    **盘中**出的票（候选取自当日实时快照、当日涨幅本身就是打分项）→ 赌【当日】封板；
