const empBucketOf = p => p >= 75 ? '75+' : p >= 65 ? '65-74' : p >= 55 ? '55-64' : p >= 45 ? '45-54' : '<45';
const empGroupOf = t => EMP_CHASE.has(t) ? '追高类' : (EMP_EARLY.has(t) ? '未启动类' : '其它');

// ── ⛔⛔ 事后样本（hindsight）判定：一切"拿历史表现反推决策参数"的地方都必须先过这一关 ──
