try {
  let _bad = 0;
  for (const sg of (S.learn.signals || [])) if (sg.prob != null && !(sg.prob > 1)) { sg.prob = null; _bad++; }
  if (_bad) { _dirty = true; console.log('[learn] 清洗概率量纲异常样本 ' + _bad + ' 条（原为0~1小数，已置空避免污染分桶）'); }
} catch {}
