    const prev = _seen.get(k);
    if (!prev) { _seen.set(k, s); _out.push(s); continue; }
    _dup++;
    if (!prev.resolved && s.resolved) prev.resolved = s.resolved;   // 回验结果是宝贵证据，继承过来
    if (prev.prob == null && s.prob != null) prev.prob = s.prob;
