  strong = strong.map(x => ({ ...x, ...auctionScoreOf(x, { amtRank: _amtRank, n: items.length || 1, amtReliable: _amtReliable, roleOf }) }))
    .sort((a, b) => b.score - a.score).slice(0, 60);
  // ⛔ 市值硬门槛：35亿以下除非特别突出（近一字或评分≥85），否则不进竞价强势池
  strong = strong.filter(x => (x.floatCap || 0) >= 3.5e9 || x.auctionPct > 9 || (x.score || 0) >= 85);
  // lz·次强档：漏网涨停的赛前特征学习产物——竞价涨 1~5%、竞价额>300万、40亿+、非 ST 的温和高开票
