function sectorHeat(sec) {
  if (!sec || sec === '未知') return { hot: false, cold: true, unknown: true, ztN: 0, rank: null, label: '❄️ 冷门·板块未知', short: '❄️冷门' };
  const n = (S.ztBySector && S.ztBySector[sec] ? S.ztBySector[sec].length : 0);
  const rank = sectorRankMap().get(sec) || null;
  const hot = n > 0 || (rank != null && rank <= 25);
  if (hot) return { hot: true, cold: false, unknown: false, ztN: n, rank, label: n > 0 ? `🔥 ${sec}·${n}只涨停` : `🔥 ${sec}·资金第${rank}`, short: n > 0 ? `🔥主线·${n}只涨停` : `🔥热门·资金第${rank}` };
  return { hot: false, cold: true, unknown: false, ztN: 0, rank, label: `❄️ 冷门·${sec}${rank ? '·资金第' + rank : ''}`, short: '❄️冷门' };
}

// ---------------- 主力大单流入识别：全市场当日主力净占比显著个股（温和上涨、未涨停）----------------
// 识别逻辑：主力净占比必须**超过**门槛(严格大于) 且 当日上涨但涨幅温和(<8%) 且 主力净额>0 → 资金真实买入而非情绪追板
