const MSG_STAT = { day: '', total: 0, by: {}, blocked: 0 };
// 第二个参数 manual：面板/API 主动触发的推送（完成度见 inManualPush）——
// ⛔ 2026-10-02 改（你要的：手动推送豁免闸门）：以前手动点的也会被「其它类每天1条」拦掉，
//    实测 10/2 一天「持仓已清空」被拦 5 次，看起来就像推送坏了。
//    注意只是【放行】，且**不占 MSG_STAT 额度** —— 否则手动多按几次，
//    会把定时推送当天的名额吃光（定时才是需要"少而精"管住的对象）。
function msgGate(text, manual) {
  const head = String(text || '').split('\n')[0] || '';
  if (MSG_FREE_RE.test(head)) return { ok: true, kind: '日报' };
  const d = (typeof todayStr === 'function') ? todayStr() : '';
  if (MSG_STAT.day !== d) { MSG_STAT.day = d; MSG_STAT.total = 0; MSG_STAT.by = {}; MSG_STAT.blocked = 0; }
  let kind = '其它';
  for (const [re, k] of MSG_TYPE_RE) { if (re.test(head)) { kind = k; break; } }
  if (manual) return { ok: true, kind };   // 手动触发：不看额度（见上方说明）
  // ⛔ go 轮 C2（用户决策「环境差就降级/少推」）：偏冷环境把总条数与各类条数减半（下限 1）。
  //    只减半、不归零 —— 冰点环境下一条不放会漏掉真正的反转信号；免配额消息在上方已 return，不受影响。
  //    0 = 不限的配置语义保持：capTotal/cap 为 0 时减半无意义，原样放行。
  const _cold = (typeof envCold === 'function') ? envCold() : false;   // go 轮 C2；typeof 守卫：msgGate 也会被守门沙箱切出真跑
  const capTotalRaw = _govCfg('pushDailyMsgs');
  const capTotal = (capTotalRaw > 0 && _cold) ? Math.max(1, Math.floor(capTotalRaw / 2)) : capTotalRaw;
  if (capTotal > 0 && MSG_STAT.total >= capTotal) return { ok: false, kind, why: `今日已推 ${MSG_STAT.total} 条，上限 ${capTotal} 条${_cold ? '（偏冷环境·额度减半）' : ''}` };
  const capRaw = MSG_CAP[kind] != null ? MSG_CAP[kind] : 1;
  // ⛔ if 轮 D2/D4：偏冷减半，但「竞价/大单」有保底线（MSG_COLD_FLOOR）—— 见常量处注释。
  //    typeof 守卫与 envCold 同款：守门套件把 msgGate 切出来真跑时不注入这个表，
  //    缺表时按无保底（floor 1）走，绝不让沙箱因 ReferenceError 静默失效。
  const _floor = (typeof MSG_COLD_FLOOR !== 'undefined' && MSG_COLD_FLOOR[kind]) || 1;
  const cap = (_cold && capRaw > 0) ? Math.max(_floor, Math.floor(capRaw / 2)) : capRaw;
  const used = MSG_STAT.by[kind] || 0;
  if (used >= cap) return { ok: false, kind, why: `今日【${kind}】已推 ${used} 条，上限 ${cap} 条${_cold ? '（偏冷环境·额度减半）' : ''}` };
  MSG_STAT.total++; MSG_STAT.by[kind] = used + 1;
  return { ok: true, kind };
}

// ⛔⛔ 返回值语义（2026-10-06 补）：**本轮是否已终结** —— true=可以置位闭锁，false=值得下轮重试。
//    为什么必须有返回值：这个函数**永不抛异常**（内部全 try/catch），被拦下时只是静默 return。
//    于是调用方写成 `xxxSentDate = ds; pushAll(...)` 时，推送其实一条都没出去，
//    但"今天已发"的闭锁已经打上了 → 当天再也不会重试 → 那条消息永久消失。
//    新闻汇总/周末汇总/假期汇总三处早就按"先发后置位"改对了，复盘/次日计划/竞价/大单/补涨龙
//    这五处是老写法，现在统一按返回值置位。
//
//    ⚠️ 关键区分：不是"拦下就重试"，只有【会自行解除】的闸门才值得重试。
//      · 夜间静默 → false（时段一过自动解除，重试有意义）
//      · 条数闸门 → true（MSG_STAT 按**天**重置，当日额度当天不会恢复，重试只是空转）
//      · 副本拦截 → true（副本设计上永不外发；返回 false 会让本地副本每 20 秒重跑一次
//                        复盘（拉涨停池 + 补拉K线）直到午夜，等于自己打自己的数据源）
//      · 无通道   → true（配置问题，重试一万次也发不出去；已进面板流水）
//    一句话：false 只留给"等一会儿就好了"的情况，否则一律 true 让本轮终结。

// 从推送正文里提取股票代码（6 位，首位 0/3/6/8/9），用于 pushlog.extra.codes 持久化，
// 让每日收盘后能把每条推送对应到具体票，统一复盘命中率。
function extractStockCodes(text) {
  try {
    const s = String(text || '');
    const set = new Set();
    // 匹配 6 位连续数字，首位限定为 A 股常见开头；前后不能是字母/数字，避免误吞长数字
    const re = /(?<![A-Za-z0-9])([03689]\d{5})(?![A-Za-z0-9])/g;
    let m;
    while ((m = re.exec(s)) !== null) set.add(m[1]);
    return Array.from(set);
  } catch (e) { return []; }
}

// ⛔ 2026-10-29：手机端「发布确认」回执去重闸（relConfirmAckKey/relConfirmAckShouldPush）已整体退役删除——
//    回执确认改为只进面板流水（pushLog）永不外发，去重闸失去对象；防重复责任上移到指令入队去重
//    （/api/release/publish 写指令前查同批文件指纹，见 _dupCmd 逻辑）。退役往事留档：
//    10-28 曾因无幂等闸 47 秒连推 17 条回执；10-29 根治「90 分钟 155 条」时确认：流程态一律不进飞书。

function pushAll(text, force, opts) {
  const delivery = prepareRecommendationDelivery(text, opts);
  if (!delivery.ok) {
    govReleaseAll(opts && opts.undo || []);
    for (const mod of (Array.isArray(opts && opts.modDay) ? opts.modDay : opts && opts.modDay ? [opts.modDay] : [])) modDayRelease(mod);
    const news=delivery.newsReview;
    if(news)_pushLast={ret:false,sent:false,why:news.status==='blocked'?'当前有效利空命中，股票推荐已暂停':'新闻状态未知，股票推荐已暂停',t:Date.now()};
    pushLog('推荐证据未通过·不外发', '[原始行缺失或不可用]', {note:news?'新闻避险：'+news.reason:delivery.kind,
      ...(news?{extra:{codes:news.reviews.map(row=>row.code).filter(code=>/^\d{6}$/.test(code||'')),newsRisk:{status:news.status,reason:news.reason,
        rows:news.reviews.slice(0,30).map(row=>({code:row.code,status:row.status,reason:row.reason,matches:row.matches.slice(0,8)}))}}}:{})});
    return false;
  }
  text = delivery.text;
  // lw（2026-10-27 用户定调⛔）：全部推送默认私密——「后面增加的所有推送都是私密，除了我特别提醒」。
  // 未显式声明 public:true 的一律 private:true（含此前走群机器人的复盘/新闻/学习日报/竞价定稿等）；
  // 确实要发群的消息在调用点显式传 { public: true }。
  if (!opts) opts = { private: true };
  else if (opts.public === true) { opts = Object.assign({}, opts); delete opts.private; }
  else if (!opts.private) opts = Object.assign({}, opts, { private: true });
  if (delivery.kind === 'historical-trigger-observation') opts = {...opts, forceHistoricalObservation:true};
  text = redactSecrets(text);   // ⛔ 凭据闸门：密码/令牌一律不许出网（2026-10-02）
  // kb 轮：把正文里的股票代码也写进 pushlog.extra，让每日收盘后能统一复盘各渠道命中率
  const _codes = extractStockCodes(text);
  const _extra = base => Object.assign({}, base, { extra: { codes: _codes,
    signalRefs: Array.isArray(opts.signalRefs) ? opts.signalRefs.map(a => ({ code: a.code, type: a.type, ts: a.ts, ...(/^[a-f0-9]{64}$/.test(a.signalId||'')?{signalId:a.signalId}:{}) })) : [] } });
  // ⛔ 2026-10-02 改：以前 essential=true 会让【副本实例也照发】（本意是"找回密码不能被副本吞掉"），
  //    实际后果是本地开发副本往用户手机狂发：找回验证码 44 条、只读申请、重置通知……
  //    这些全是用户在【线上】面板触发的动作，线上(primary)实例自己会发，副本没有任何理由插手。
  //    → 现在副本对外发一律说不（验证码在副本上改为本机回显），只保留 manual（本机面板主动点的）例外。
  // 定时任务没有请求上下文，仍被拦截 → 只有线上推，手机不会一次来两份。
  const _manual = !!(opts && opts.manual) || inManualPush();
  if (isReplica() && !_manual) {
    // 面板照样实时刷新，只是不往手机/邮箱外发
    console.log('[replica] 本实例为副本，拦截定时外发推送:', String(text).slice(0, 50).replace(/\n/g, ' '));
    pushLog('副本拦截(不外发)', text, _extra({ note: '本实例是副本，定时推送一律不对外发，只有线上实例才推' }));
    try {
      const evt = { time: new Date().toLocaleTimeString('zh-CN'), preview: String(text).replace(/<[^>]+>/g, '').replace(/\n+/g, ' | ').slice(0, 260) };
      if (opts && (opts.private || opts.sseEdit)) sseSendEdit('alert', evt); else sseSend('alert', evt);
    } catch {}
    _pushLast = { ret: true, sent: false, why: '副本拦截（本实例不外发）', t: Date.now() };
    return true;   // 副本：本轮终结（不对外发，但也不能让调用方无限重试烧数据源）
  }
  // 「少而精」条数闸门：超限就只进面板流水、不往手机发。
  // 面板照样能查到被拦了什么（/api/push-log），免得"没收到"又说不清是被拦还是坏了。
  const _mg = msgGate(text, _manual);   // 手动触发的不受"少而精"条数限制（定时任务照样管）
  if (!_mg.ok) {
    MSG_STAT.blocked++;
    console.log('[少而精] 拦截 ' + _mg.kind + '：' + _mg.why);
    pushLog('🚫 条数闸门', text, _extra({ note: _mg.why + '（内容已进面板推送流水，完整榜单见面板）' }));
    _pushLast = { ret: true, sent: false, why: '条数闸门：' + (_mg.why || ''), t: Date.now() };
    return true;   // 额度按天重置，当天重试无用 → 本轮终结（内容已进面板流水）
  }
  if (inQuietHours() && !force) {
    const _q2 = m => String(Math.floor(m / 60)).padStart(2, '0') + ':' + String(m % 60).padStart(2, '0');
    const _q = quietWindow();
    const _qs = _hhmm(_q.start, 0 * 60 + 30), _qe = _hhmm(_q.end, 8 * 60 + 30);
    console.log('[夜间静默 ' + _q2(_qs) + '-' + _q2(_qe) + '] 拦截推送:', text.slice(0, 50).replace(/\n/g, ' '));
    pushLog('夜间静默拦截', text, _extra({ note: '静默时段 ' + _q2(_qs) + '-' + _q2(_qe) }));
    _pushLast = { ret: false, sent: false, why: '夜间静默', t: Date.now() };
    return false;   // 夜间静默拦下：没发出去
  }
  if (typeof process!=='undefined'&&process.env.V6_AUTO_STOCK_OBSERVATIONS==='1'&&typeof queuePushedStockObservations==='function') {
    try{queuePushedStockObservations(text,_codes,opts);}catch{console.error('[research-observation] 意图封存失败，推送继续');}
  }
  // 实时通道：任何一条推送同步触达面板，打开着的页面立即刷新（不用等轮询）
  // opts.private=true 属于私密消息（如持仓风控），只推给开发者连接，观看(只读)连接收不到
  // opts.sseEdit=true 只影响 SSE 分流（同样只发开发者连接），**不改变外发目的地** ——
  //   给「该本人看见、但外发通道不该改」的消息用（如模拟盘动态：它照旧发主机器人，
  //   但内容含账户金额与逐笔买卖，不能广播给只读观看者的面板）。
  try {
    const evt = {
      time: new Date().toLocaleTimeString('zh-CN'),
      preview: String(text).replace(/<[^>]+>/g, '').replace(/\n+/g, ' | ').slice(0, 260)
    };
    if (opts && (opts.private || opts.sseEdit)) sseSendEdit('alert', evt); else sseSend('alert', evt);
  } catch {}
  // ⛔ 2026-10-05 新增：私密消息（opts.private）在配了私密机器人后【只发私密机器人】，
  //    不再往群里那个共享机器人发，也不发邮箱 —— 持仓的金额、验证码都只该本人看见。
  //    没配私密通道则记录私密未送达，不改发公共通道。
  //    ⚠️ 位置很讲究：必须排在副本拦截/条数闸门/夜间静默/面板推送【之后】，
  //       这样私密化只是"换个收件人"，不会顺手把静默和额度一起绕过去。
  // ⛔⛔ 2026-10-06（本轮角度：占位与送达的原子性）：确认没送到 → 把这一批占位退回去。
  //   见 govRelease 的注释：额度/冷却/去重/模块配额是**发送之前**就占上的，
  //   发送失败若不退回，这条消息当天就永久消失（下一轮会因为"已推过"直接跳过它）。
  //   只在确认未发送时退回占位；私密通道结果未知保留去重，任何失败均不改发群。
  const _undo = opts && opts.undo;
  let _released=false;
  const _release = (why) => {
    if (_released) return;
    _released=true;
    try {
      govReleaseAll(_undo || []);
      if (opts && opts.modDay) {
        const ms = Array.isArray(opts.modDay) ? opts.modDay : [opts.modDay];
        for (const mm of ms) modDayRelease(mm);
      }
      pushLog('↩️ 占位已退回', text, _extra({ note: '发送失败（' + why + '），额度/冷却/去重已撤销，下一轮会补推' }));
    } catch (e) { console.error('[gov] 占位回滚失败:', e && e.message); }
  };
  const _newsBeforeSend = delivery.requiresNewsReview ? () => {
    const review=recommendationNewsReview(delivery.newsRows);
    if(review.canRecommend)return {ok:true};
    const why='新闻避险未通过：'+review.reason;
    _pushLast={ret:false,sent:false,why,t:Date.now()};
    const info=_extra({note:why});info.extra.newsRisk={status:review.status,reason:review.reason,
      rows:review.reviews.slice(0,30).map(row=>({code:row.code,status:row.status,reason:row.reason,matches:row.matches.slice(0,8)}))};
    pushLog('新闻避险·该次发送暂停','[当前发送尝试已暂停]',info);
    return {ok:false,why};
  } : null;
  if (opts && opts.private) {
    if (!privReady()) {
      _pushLast = { ret: true, sent: false, why: '私密通道未配置', t: Date.now() };
      pushLog('🔒 私密未送达·不外发', '[私密消息已隐藏]', _extra({ channel: '飞书·私密' }));
      _release('私密通道未配置');
      return false;
    }
    if (_newsBeforeSend) { const checked=_newsBeforeSend();if(!checked.ok){_release(checked.why);return false;} }
    feishuSendPrivate(text, {...opts, manual:_manual,
      // The body has already been rewritten before a historical observation
      // enters this queue. A current recommendation remains current and must
      // still pass the upstream queue's 15-second quote recheck.
      forceHistoricalObservation:opts.forceHistoricalObservation||delivery.kind==='historical-trigger-observation',
      ...((delivery.newsRows)?{newsRecommendationRows:delivery.newsRows}:{}),
      beforeSend:_newsBeforeSend||undefined}).then(r => {
      if(r&&r.localReview){
        _pushLast={ret:false,sent:false,why:r.localReview.why||'派发前新闻审核未通过',t:Date.now()};
        _release(_pushLast.why);return;
      }
      if (r && r.ok) { _pushLast = { ret: true, sent: true, why: '', t: Date.now() }; pushLog('✅ 已送达(私密)', text, _extra({ channel: '飞书·私密', note: '仅本人可见：' + feishuSecMask() })); return; }
      // ⛔⛔ fz 轮：私密通道「结果未知」（超时/断连）时**不许退回群机器人**。
      //    消息很可能已经送到本人手上了，再往群里补一条 = 同一条内容来两遍（用户反复投诉的那种重复）；
      //    而且私密内容退回群发本身就是把"仅本人可见"的东西广播出去，两头都错。
      //    飞书明确拒绝也只记录私密失败，不得公开发送。
      if (sendResultUnknown(r && r.msg)) {
        _pushLast = { ret: true, sent: false, why: '私密通道送达结果未知（未退回群，避免重复）', t: Date.now() };
        pushLog('⚠️ 送达结果未知(私密)', text, _extra({
          channel: '飞书·私密', error: (r && r.msg) || '',
          note: '超时/网络异常：私密消息可能已经送到本人，只是没拿到回执。不再改发群机器人（既会重复、又会泄露），也不撤销去重；确实没收到可在面板手动补发'
        }));
        return;
      }
      // ⛔⛔ 2026-10-28 改（用户铁律：所有推送一律私密通道，发群必须显式 {public:true}）：
      //    以前这里【私密明确拒绝也一律退回群机器人】，理由是「验证码有时效，不能让人收不到」。
      //    但这条兜底对【所有 private 消息】都生效 —— 2026-10-28 09:16-09:17 早盘私密通道被限频，
      //    竞价共振/封板哨兵/板块暴动就是这样被发进公开群的（当日流水 channel='飞书(退回)' 8 条）。
      //    行情内容退回群 = 未经授权的外发，比「今天少推一条」严重得多。
      //    → 现在即使 mustDeliver 为 true，也绝不能退回公开通道；
      //      其余内容私密没送到就只记流水 + 退回占位，下一轮继续走私密补推（宁可少推，不可错推）。
      // Private content is never eligible for a public fallback, including mustDeliver.
      console.error('[priv] 私密机器人拒收；禁止退回公共群:', (r && r.msg) || '');
      _pushLast = { ret: true, sent: false, why: '私密通道拒收（禁止公开退回）', t: Date.now() };
      pushLog('🔒 私密未送达·不外发', '[私密消息已隐藏]', _extra({ channel: '飞书·私密', note: '仅私密通道允许发送；未退回公共群' }));
      _release('私密通道拒收');
    }).catch(e => {
      // ⛔ fz 轮：同上，异常若是超时/断连也按「结果未知」处理，不退回群（否则重复 + 泄露）。
      //    代码级异常（如读不到配置）也不得公开发送。
      if (sendResultUnknown(e && e.message)) {
        _pushLast = { ret: true, sent: false, why: '私密通道异常且结果未知（未退回群）', t: Date.now() };
        pushLog('⚠️ 送达结果未知(私密)', text, _extra({ channel: '飞书·私密', error: String((e && e.message) || e), note: '超时/网络异常，未改发群机器人（避免重复与泄露）' }));
        return;
      }
      // 同上（2026-10-28）：代码级异常也按私密策略处理，任何 mustDeliver 值均不得外发群。
      console.error('[priv] 私密通道异常；禁止退回公共群:', (e && e.message) || e);
      _pushLast = { ret: true, sent: false, why: '私密通道异常（禁止公开退回）', t: Date.now() };
      pushLog('🔒 私密未送达·不外发', '[私密消息已隐藏]', _extra({ channel: '飞书·私密', note: '异常未退回公共群' }));
      _release('私密通道异常');
    });
    if (_pushLast.sent !== true) _pushLast = { ret: true, sent: null, why: '私密通道异步发送中', t: Date.now() };
    return true;   // ⛔ 私密已接管：绝不再往下走群机器人 + 邮箱（否则等于私密了个寂寞）
  }
  // 通道1：飞书自定义机器人（2026-09-28 起取代企业微信：企业微信渠道已整体移除）
  // 通道2：QQ邮箱（需配置授权码）
  // ⛔ 2026-10-06 补（本轮角度：错误分支里的资源与状态回滚）：
  //    「这一条通道失败了」**不等于**「这条消息没送到」—— 另一条通道可能已经送到本人手上了。
  //    旧写法在飞书回调里直接 _release 把额度/冷却/去重退回去，
  //    于是下一轮会照原样再推一遍：飞书没收到的人什么都没变，邮箱那头却收到【两条一模一样的】。
  //    回滚判据必须是「所有启用的通道都没送到」，所以这里等两边都有结论再决定。
  const m = S.config.qqMail;
  const _mailOn = mailReady();   // ⛔ 与面板显示的"邮箱已配置"同一把尺子（见 mailReady 注释）
  // ⛔ fz 轮：连同**回执原文**一起记下来 —— 光有 true/false 分不清"被拒绝"和"没回音"，
  //    而这两者的处置正好相反（一个可以补推，一个绝不能补推，否则就是重复）。
  let _fsOk = null, _fsInfo = '', _mailOk = _mailOn ? null : false, _mailInfo = '';
  const _settle = () => {
    if (_fsOk === null || _mailOk === null) return;     // 还有通道没回话，再等等
    // ⛔ dl 轮：顺带把「到底送没送出去」定格下来 —— 以前只有"返回 true"，
    //    而 true 里混着「已送达」与「被闸门拦下根本没发」，面板与流水都看不出区别。
    if (_fsOk || _mailOk) { _pushLast = { ret: true, sent: true, why: '', t: Date.now() }; return; }
    // ⛔⛔ fz 轮：任一通道是「结果未知」（超时/断连）就**不许撤销去重占位**。
    //    消息很可能已经躺在用户手机上了，撤销 = 下一轮再发一遍 = 用户看到两条。
    const _unknown = (_fsOk === false && sendResultUnknown(_fsInfo))
      || (_mailOn && _mailOk === false && sendResultUnknown(_mailInfo));
    if (_unknown) {
      _pushLast = { ret: true, sent: false, why: '送达结果未知（未重推，避免重复）', t: Date.now() };
      pushLog('⚠️ 送达结果未知', text, _extra({
        channel: _fsOk === false ? '飞书' : '邮箱',
        error: _fsOk === false ? _fsInfo : _mailInfo,
        note: '超时/网络异常：消息可能已经送到，只是没拿到回执。为免重复推送，本轮不撤销去重、不再重推；确实没收到可在面板手动补发'
      }));
      return;   // ⛔ 注意：这里**故意不调 _release**
    }
    _pushLast = { ret: true, sent: false, why: _mailOn ? '飞书与邮箱都没送到' : '飞书未送达', t: Date.now() };
    _release(_mailOn ? '飞书与邮箱都没送到' : '飞书未送达');
  };
  _pushLast = { ret: true, sent: null, why: '异步发送中', t: Date.now() };
  feishuSend(text, (ok, info) => {
    if (ok) pushLog('✅ 已送达', text, _extra({ channel: '飞书' }));
    else pushLog('❌ 发送失败', text, _extra({ channel: '飞书', error: info }));
    _fsOk = !!ok; _fsInfo = String(info || ''); _settle();
  }, _newsBeforeSend ? {beforeSend:_newsBeforeSend} : undefined);
  const _mailReview=_mailOn&&_newsBeforeSend?_newsBeforeSend():{ok:true};
  if (_mailOn && !_mailReview.ok) { _mailOk=false;_mailInfo=_mailReview.why;_settle(); }
  if (_mailOn && _mailReview.ok) {
    sendQQMail({ user: m.user, authCode: m.authCode, to: m.to, subject: '【量化看盘】实时信号', text })
      .then(() => { pushLog('✅ 已送达', text, _extra({ channel: '邮箱' })); _mailOk = true; _settle(); })
      .catch(e => { console.error('[mail]', e && e.message); pushLog(sendResultUnknown(e && e.message) ? '⚠️ 送达结果未知' : '❌ 发送失败', text, _extra({ channel: '邮箱', error: String((e && e.message) || e) })); _mailOk = false; _mailInfo = String((e && e.message) || e); _settle(); });
  }
  // ⛔ 判据必须与 mailReady() 同一把尺子（2026-10-07）：原来这里只查 user+authCode、漏了收件人 to，
  //    于是"邮箱填了一半"时既不算已配、也不记这条「未配置通道」—— 面板流水里只剩一句
  //    「发送失败：未配置飞书机器人地址」，把人往飞书上引，可真正缺的是收件人。
  if (!feishuReady() && !mailReady()) {
    console.log('[push未配置]', text.slice(0, 60));
    pushLog('⚠️ 未配置通道', text, _extra({ note: '既没配飞书机器人也没配邮箱（邮箱需账号+授权码+收件人三项齐全）' }));
    _pushLast = { ret: true, sent: false, why: '未配置通道（飞书与邮箱都没配）', t: Date.now() };
    return true;   // 配置问题，重试无用 → 本轮终结（已记「未配置通道」流水）
  }
  return true;
}
const pushWecom = pushAll; // 兼容旧调用

// ---------------- 模拟盘动态：分笔买入/卖出攒成一条汇总，不再一笔一条 ----------------
// 实测 10:06:12 卖出、10:10:52 买入、10:11:32 买入 各来一条，和盘中快报叠在一起很吵。
const PAPER_PUSH = { buf: [], timer: null, lastSent: 0 };
const PAPER_PUSH_GAP = 5 * 60 * 1000;    // 两条模拟盘汇总最短间隔 5 分钟
const PAPER_PUSH_WAIT = 90 * 1000;       // 命中后最多等 90 秒必发
function pushPaperDigest(line) {
  PAPER_PUSH.buf.push(line);
  if (PAPER_PUSH.timer) return;
  const wait = Math.max(5000, Math.min(PAPER_PUSH_WAIT, PAPER_PUSH_GAP - (Date.now() - PAPER_PUSH.lastSent)));
  PAPER_PUSH.timer = setTimeout(() => {
    PAPER_PUSH.timer = null;
    const items = PAPER_PUSH.buf; PAPER_PUSH.buf = []; PAPER_PUSH.lastSent = Date.now();
    if (!items.length) return;
    // ⛔ 2026-10-06 补：这条含【账户金额 + 逐笔买卖明细】，属于和持仓同级的私密数据。
    //    以前没打任何私密标记 → 走 sseSend('alert') **广播给所有 SSE 连接**，
    //    只读（观看）设备的面板照样弹得出你几点几分买了什么、卖了多少钱。
    //    这里用 sseEdit 而不是 private：外发仍走当前主机器人（行为不变），只把面板广播收窄到开发者连接。
    // ⛔ go 轮 A10（2026-10-13）：用户决策「模拟盘动态 → 改私密」—— 外发也从群机器人改为私密机器人
    //    （sseEdit 保留：只读连接本来就不该看到账户明细，两个标记各管一头，不互相替代）。
    pushAll(`═══ 💰 模拟盘动态 ═══\n` + items.join('\n') + '\n（模拟盘分笔操作每 5 分钟合并汇总一次，逐笔明细见面板）', false, { sseEdit: true, private: true });
  }, wait);
}

// ---------------- 飞书自定义机器人（唯一主通道，2026-09-28 取代企业微信）----------------
// 机器人地址形如 https://open.feishu.cn/open-apis/bot/v2/hook/<id>
// 若群里开启了「签名校验」，把密钥填进 feishuSecret，会自动带上 timestamp + sign。
function feishuId() {
  const m = String(process.env.V6_FEISHU_PUBLIC_WEBHOOK || (S.config && S.config.feishuWebhook) || '').match(/open-apis\/bot\/v2\/hook\/([\w-]+)/);
  return m ? m[1] : '';
}
function feishuReady() { return !!feishuId(); }
// ⛔ 邮箱「可用」的唯一判据（2026-10-07 收口 · 本轮角度：系统对自己说的话负不负责）。
//    以前同一个问题在四处各写了一遍，其中两处**漏了收件人 to** ——
//    面板于是显示「邮箱已配置 ✅」，而真正发信的 pushAll 要求 user+authCode+to 三者齐全，
//    缺 to 时它压根不尝试发信。系统对外说"通道已配好"，自己发的时候却当它没配 —— 话和责任对不上。
//    现在只此一处：user（账号）+ authCode（授权码）+ to（收件人）缺一不可。
function mailReady() {
  const m = S.config && S.config.qqMail;
  return !!(m && m.user && m.authCode && m.to);
}
// 打码显示机器人地址：让人认得出"是哪一台"，又不把完整地址摆出来（拿到地址＝能往群里发消息）
function maskHook(raw) {
  const s = String(raw || '');
  const m = s.match(/open-apis\/bot\/v2\/hook\/([\w-]+)/);
  const id = m ? m[1] : '';
  if (!id) return '(未配置)';
  return id.length <= 8 ? (id.slice(0, 2) + '****') : (id.slice(0, 4) + '****' + id.slice(-4));
}
function feishuMask() { return maskHook(process.env.V6_FEISHU_PUBLIC_WEBHOOK || (S.config && S.config.feishuWebhook)); }
// ── 私密发布通道（2026-10-05 用户要求：「人有点多的话可能会被盗用/恶意改密码」──
//    「持仓和验证码能不能推送到单独机器人，这样持仓就可以把金额显示出来了」）──
// 问题一（安全）：找回密码的验证码原先走 pushAll → 发到【群里那个共享机器人】，
//       群里每个人都能看见验证码，等于把「改开发者密码」的权力公开在群里，
//       任何看到码的人都能在有效期内完成验证并重置密码。
// 问题二（隐私）：持仓推送因为发在群里，只能把成本/金额/股数全部抹掉（见 holdings.js 的 stripAmt），
//       风控消息看得见"该止损"却看不见"亏了多少"，等于隔靴搔痒。
// 做法：单独配一个只有本人在的机器人（feishuSecWebhook），
//       【验证码 + 持仓】两类消息全部只发它、不进群；没配则停止私密发送并记录失败，
//       绝不因为配了私密通道就把没配的部署弄成"推不出去"。
// ⛔ 判定私密与否只看 feishuSecReady()（有地址且格式合法），与"群里那个"完全独立：
//    私密通道不通时停止发送并记录失败，绝不向公共群退回验证码或持仓。
function feishuSecId() {
  const m = String(process.env.V6_FEISHU_PRIVATE_WEBHOOK || (S.config && S.config.feishuSecWebhook) || '').match(/open-apis\/bot\/v2\/hook\/([\w-]+)/);
  return m ? m[1] : '';
}
function feishuSecReady() { return !!feishuSecId(); }
function feishuSecMask() { return maskHook(process.env.V6_FEISHU_PRIVATE_WEBHOOK || (S.config && S.config.feishuSecWebhook)); }
// 语义别名：这一路叫「私密通道」而不是「安全通道」，因为它不只管验证码，也管持仓。
// holdings.js 据此决定要不要把金额写出来 —— 走私密才写，走群里一律抹掉。
function privReady() { return feishuSecReady(); }
// 往指定机器人直推一条体检消息，并**同步等飞书回包**。
// ⚠️ 不走 _fsQueue（队列是异步的，拿不到结果）+ 不改 S.config（体检归体检，落盘归落盘）。
// 第三参 _https 是为了单测注入假模块（不传则为真实 https）。
// 参数顺序踩过坑：注入用的假 https 原先排在第三个位置，结果业务侧想传文案时
// 一不留神就把字符串塞进了注入参数，表现为 "mod.request is not a function" ——
// node --check 查不出，只有真发一次才炸。现在把注入口挪到最后，正常调用永远是
// (机器人 id, 密钥, 文案)，注入只出现在测试里。
function feishuProbe(id, secret, text, _https) {
  return new Promise(resolve => {
    let settled = false;
    const done = r => { if (!settled) { settled = true; resolve(r); } };
    let mod;
    try { mod = _https || require('https'); }
    catch (e) { return done({ ok: false, msg: '无法发起网络请求: ' + ((e && e.message) || e) }); }
    const payload = { msg_type: 'text', content: { text: stripHtmlTags(text || '✅ 通道体检：该飞书机器人已接通（如非本人操作请忽略）') } };
    if (secret) {
      try {
        const ts = Math.floor(Date.now() / 1000);
        payload.timestamp = String(ts);
        // Feishu signs an empty message with timestamp + newline + secret as the HMAC key.
        payload.sign = crypto.createHmac('sha256', ts + '\n' + secret).update('').digest('base64');
      } catch (e) { return done({ ok: false, msg: '签名密钥异常: ' + ((e && e.message) || e) }); }
    }
    const buf = Buffer.from(JSON.stringify(payload), 'utf8');
    let req;
    try {
      req = mod.request({
        hostname: 'open.feishu.cn', path: '/open-apis/bot/v2/hook/' + id, method: 'POST', timeout: 8000,
        headers: { 'Content-Type': 'application/json; charset=utf-8', 'Content-Length': buf.length }
      }, res => {
        let b = '';
        try { res.on('data', d => b += d); } catch (e) {}
        res.on('end', () => {
          let j = null; try { j = JSON.parse(b); } catch (e) {}
          done(classifyFeishuReceipt(res.statusCode, j));
        });
        res.on('aborted', () => done({ok:false,msg:'送达结果未知：响应中断'}));
        res.on('error', () => done({ok:false,msg:'送达结果未知：响应流错误'}));
      });
    } catch (e) { return done({ ok: false, msg: '请求构造失败: ' + ((e && e.message) || e) }); }
    req.on('timeout', () => { try { req.destroy(); } catch (e) {} done({ ok: false, msg: '请求超时（8 秒无响应）' }); });
    req.on('error', e => done({ ok: false, msg: '网络异常: ' + ((e && e.message) || e) }));
    try { req.end(buf); } catch (e) { done({ ok: false, msg: '发送失败: ' + ((e && e.message) || e) }); }
  });
}

// 把飞书的错误原话翻译成「人话 + 下一步干什么」（2026-10-03）
// 教训：以前失败只在流水里留一串 code=9499 too many request，用户看着一脸茫然，
//       要么以为自己手机坏了，要么反复重发把限流搞得更严重。现在必须给出可执行的下一步。
function feishuErrTip(msg) {
  const m = String(msg || '');
  const cm = m.match(/code=(-?\d+)/);
  const code = cm ? cm[1] : '';
  if (code === '11232' || /HTTP 429|too many request/i.test(m)) return '飞书限流了（同一时间发太多）。这不是地址坏了，等 1~2 分钟再点一次自检即可。';
  if (code === '9499') return '飞书拒绝了请求参数，请检查消息格式；更换机器人地址通常不能解决。';
  if (code === '19021' || /签名|sign|signature/i.test(m)) return '签名校验没过：群里如果没开「签名校验」，请把密钥那一栏清空再试；开了的话检查密钥与服务器时间。';
  if (/送达结果未知/.test(m)) return '未取得有效回执，暂不自动重推。请先核对飞书消息和网络状态。';
  if (/invalid|not exist|不存在|已删除|解散|robot/i.test(m)) return '这个机器人地址已失效（机器人被删除 / 群已解散）。请到飞书群里重新添加机器人，再把新地址复制进来。';
  if (/超时|timeout|ETIMEDOUT/i.test(m)) return '连不上飞书服务器（超时）。检查网络/代理后重试。';
  if (/ENOTFOUND|EAI_AGAIN|网络异常/i.test(m)) return '域名解析失败，检查网络或代理设置。';
  return '飞书返回：' + m.slice(0, 60) + '。若反复失败，多半是机器人被删或群已解散 —— 重新在群里加一个机器人再换地址。';
}

// ⛔⛔ 2026-10-09 fz 轮：区分「确认没送到」与「结果未知」—— 重复推送真正的根因
// ---------------------------------------------------------------------------
// 用户 10-08「复盘推了六遍」、10-09「飞书你又重复推送」。前几轮修的都是**重启重放**
// （内存闭锁清零后用落盘流水兜住），但还有一条一直没人动：
//
//   超时 / 断连 **不等于** 没送到。请求已经出了网，飞书很可能已经把消息投递出去了，
//   只是回执没回来（云端出网本就抖，见 §8）。而旧逻辑一律当成「确认失败」：
//     pushAll 收到 ok=false → _release() 把「额度/冷却/去重」占位全部撤销
//     → 下一轮定时器一问「今天发过没」→ 去重已被撤销、流水里也没有 ✅ 送达记录
//     → 判定"今天还没发" → **照原样再推一遍** → 用户收到两条一模一样的。
//
//   而且这条路径会自我放大：网络越差，超时越多，撤销越频繁，重推越多，重复越严重。
//
// → 只有飞书**明确拒绝**才算确认未送达（此时撤销占位、允许下一轮补推）；
//   超时/断连/看门狗兜底一律算「结果未知」，**不撤销去重**，宁可少发一条也不重复。
//   流水里写清楚「结果未知·未重推」，用户要补可以在面板手动发（manual 不受去重限制）。
function sendResultUnknown(info) {
  const s = String(info || '');
  if (/送达结果未知/.test(s)) return true;
  if (!s) return false;                                                    // 没信息就当确认失败
  if (/超时|timeout|ETIMEDOUT|ESOCKETTIMEDOUT|未回调/i.test(s)) return true;
  if (/ECONNRESET|ECONNABORTED|EPIPE|socket hang up|ENOTFOUND|EAI_AGAIN|EHOSTUNREACH|ENETUNREACH|ECONNREFUSED/i.test(s)) return true;
  if (/网络异常|请求失败|Premature|aborted/i.test(s)) return true;
  return false;   // 其余（code=9499 限频、code=xxxx 业务错误）= 明确拒绝，确认没送到，可以补推
}

// ── 飞书发送串行队列 + 限频重试（2026-09-29 线上实测事故修的） ──────────────
// 现象：同一次 tick 里会连着触发好几类信号（竞价异动 / 补涨龙 / 模拟盘 …），
// 原先 `pushAll` 是**来一条就并发打一次 open.feishu.cn**，同一秒能冲出 5 条，
// 结果线上 push-log 里出现：
//   ❌ 发送失败 code=9499 too many request
// → 用户实际少收到消息，而且丢的是随机一条，**丢了他也不知道**，属于静默失败。
// 做法：串行队列 + 两条之间最小间隔；撞限频时退避重发（最多 2 次）。
// 队列有上限，极端堆积时丢最旧的并记日志 —— 宁可丢一条旧快报，也不能让内存被撑爆。
// 调度实现放 feishuq.js（可注入假时钟做单测），下面只是接线。
const FSQ = require('./feishuq.js');
const _fsQueue = FSQ.createQueue(
  (text, cb) => feishuSendOnce(text, cb),
  { minGap: 1200, maxQ: 200, retry: 2, log: { warn: m => console.warn('[feishu] ' + m), error: m => console.error('[feishu] ' + m) } }
);
// Default-private business messages use the same bounded scheduling guarantees.
// Credentials are captured when queued so a config change cannot redirect an old message.
const _fsPrivateQueue = FSQ.createQueue(
  (job, cb) => {
    if (isReplica() && !job.options.manual) return cb(false, '本实例已切为副本，排队消息未发送');
    if (job.id !== feishuSecId() || job.secret !== (process.env.V6_FEISHU_PRIVATE_SECRET || (S.config && S.config.feishuSecSecret) || ''))
      return cb(false, '私密通道配置已变更，排队消息未发送');
    if (job.options.recommendationRows && !job.options.forceHistoricalObservation &&
        !prepareRecommendationDelivery(job.text, job.options).canRecommend)
      return cb(false, '排队期间推荐证据失效，未发送');
    return feishuProbe(job.id, job.secret, job.text).then(r => cb(r.ok, r.msg), () => cb(false, '送达结果未知：私密请求异常'));
  },
  { minGap: 1200, maxQ: 200, retry: 2, log: { warn: m => console.warn('[feishu-private] ' + m), error: m => console.error('[feishu-private] ' + m) } }
);
function feishuSendPrivate(text, opts) {
  const options={...opts};
  if(Array.isArray(options.recommendationRows))options.recommendationRows=Object.freeze(options.recommendationRows.map(row=>Object.freeze({...row,
    sectors:Object.freeze(Array.isArray(row.sectors)?row.sectors.slice():[])})));
  if(Array.isArray(options.newsRecommendationRows))options.newsRecommendationRows=freezeNewsRecommendationRows(options.newsRecommendationRows);
  const job = {id:feishuSecId(), secret:process.env.V6_FEISHU_PRIVATE_SECRET || (S.config && S.config.feishuSecSecret) || '', text, options};
  if (!job.id) return Promise.resolve({ok:false,msg:'私密通道未配置'});
  let localReview=null;
  const queueOptions={...options};
  if(typeof options.beforeSend==='function')queueOptions.beforeSend=()=>{
    try{const checked=options.beforeSend();if(checked!==true&&(!checked||checked.ok!==true))localReview=checked||{ok:false,why:'新闻审核未通过'};return checked;}
    catch(_){localReview={ok:false,why:'新闻审核不可用'};return localReview;}
  };
  return new Promise(resolve => _fsPrivateQueue.send(job, (ok, msg) => resolve({ok,msg,...(localReview?{localReview}:{})}), queueOptions));
}

// opts.priority = true 的消息插到队首：验证码 / 凭证卡这类有时效的东西不能排在一堆行情快报后面。
function feishuSend(text, cb, opts) { _fsQueue.send(text, cb, opts); }

function feishuSendOnce(text, cb) {
  const id = feishuId();
  // ⛔ 2026-10-06 补（本轮角度：错误分支里的资源与状态回滚）：
  //    这个函数的每一条出口**都必须把结果交给回调** —— 飞书队列是靠回调把 running 还回去的，
  //    漏一次就永久锁死（详见 feishuq.js 顶部说明）。旧版在"根本没配机器人地址"时直接 return，
  //    连回调都不调；网络请求那边也没设超时，对端接了不回话就永远没有下文。
  //    现在统一走 done：成功、失败、超时、未配置，四条路都有交代，且只结算一次。
  let _settled = false;
  const done = (ok, info) => { if (_settled) return; _settled = true; if (cb) cb(ok, info); };
  if (!id) {
    if (S.config && S.config.feishuWebhook) {
      console.error('[feishu] ❌ 机器人地址无效，应形如 https://open.feishu.cn/open-apis/bot/v2/hook/xxxx');
      console.error('[feishu] 未发出的消息:', String(text).slice(0, 80));
      return done(false, '机器人地址无效（缺少 /open-apis/bot/v2/hook/ 部分）');
    }
    // 没配就明说"没配"，别一声不吭地走掉 —— 那正是把队列锁死的那种静默
    return done(false, '未配置飞书机器人地址');
  }
  const payload = { msg_type: 'text', content: { text: stripHtmlTags(text) } };
  const secret = process.env.V6_FEISHU_PUBLIC_SECRET || (S.config && S.config.feishuSecret) || '';
  if (secret) {
    try {
      const ts = Math.floor(Date.now() / 1000);
      payload.timestamp = String(ts);
      payload.sign = crypto.createHmac('sha256', ts + '\n' + secret).update('').digest('base64');
    } catch { return done(false, '签名密钥异常'); }
  }
  const body = Buffer.from(JSON.stringify(payload), 'utf8');
  const req = require('https').request({
    hostname: 'open.feishu.cn', path: `/open-apis/bot/v2/hook/${id}`, method: 'POST',
    headers: { 'Content-Type': 'application/json; charset=utf-8', 'Content-Length': body.length }
  }, r => {
    let b = '';
    r.on('data', d => b += d);
    r.on('end', () => {
      let j = null;
      try { j = JSON.parse(b); } catch {}
      // 飞书成功返回 {"code":0,"msg":"success"}；失败返回非 0 code + msg
      const receipt = classifyFeishuReceipt(r.statusCode, j);
      done(receipt.ok, receipt.msg);
    });
    r.on('aborted', () => done(false, '送达结果未知：响应中断'));
    r.on('error', () => done(false, '送达结果未知：响应流错误'));
  });
  // ⛔ 没有超时的话：对端接受连接却迟迟不响应（代理挂住 / socket 半开），
  //    这个请求就永远没有下文，回调不来 → 队列永久锁死。15 秒足够飞书应答。
  req.setTimeout(15000, () => {
    console.error('[feishu] 请求超时（15s 无响应），按失败结算');
    try { req.destroy(); } catch {}
    done(false, '请求超时（15s 无响应）');
  });
  req.on('error', e => { console.error('[feishu] 请求失败', e && e.message); done(false, (e && e.message) || String(e)); });
  req.end(body);
}

// 将同一轮触发的信号聚合为一条精美的盘中快报（飞书推送格式）
// 面板 signals 记录（a.msg 单行格式）保持不变，仅推送文案升级排版
// ---------------- 推送增强：上涨概率预判 + 选股逻辑 + 风险提示（让用户看清再追，避免损失） ----------------
// 「后续上涨概率」：与「涨停概率」区分开 —— 前者是"接下来还涨的可能性"，后者是"封板的可能性"
function riseProbOf(s, opt) {
  const o = opt || {};
  let p = 50;
  if ((s.mainPct || 0) > 5) p += 14;
  else if ((s.mainPct || 0) > 3) p += 10;
  else if ((s.mainPct || 0) > 0) p += 5;
  else p -= 12;                                 // 主力净流出 → 概率打折
  p += Math.min((o.condCount || 0) * 6, 18);     // 命中的技术条件越多越强
  if ((s.pct || 0) >= 8) p -= 10;                // 涨幅过高 → 回吐/炸板风险大
  else if ((s.pct || 0) >= 5) p -= 4;
  if (o.up3) p += 6;                             // 连续 3 日上涨（趋势惯性）
  if (o.fund3d) p += 5;                          // 三日资金净流入
  if (o.goodHit) p += 6;                         // 利好催化
  if (o.badHit) p -= 12;                         // 利空压制
  return Math.max(15, Math.min(92, Math.round(p)));
}
// 风险提示：把"追高前该知道的事"直接写进推送
function riskNoteOf(s, opt) {
  const o = opt || {};
  const r = [];
  if (o.badHit) r.push('命中利空雷达（有负面消息，慎追）');
  if ((s.pct || 0) >= 8) r.push('涨幅已高，追高需谨慎');
  else if ((s.pct || 0) >= 5) r.push('涨幅偏高，注意回落');
  if (o.gap != null && o.gap > 0 && o.gap < 1) r.push(`距涨停仅${o.gap.toFixed(1)}%，封板不确定`);
  if ((s.mainPct || 0) < 0) r.push('主力净流出');
  if (o.goodHit) r.push('✅ 利好关联');
  return r.length ? r.join(' | ') : '暂无特殊风险';
}
// 参考止损：现价 -3%，跌破即离场
// ⛔⛔ 2026-10-08 改（本轮角度：只有结论、没有前提的话）：注释原来写「与模拟盘 sl 一致」——
//    **根本不一致**。模拟盘真正执行的是账户里配置的 `stopPct`（默认 -8，持仓页可改，
//    holdings.js 的 `HOLD.stopPct`），这里是写死的 -3%。两套止损差 5 个点，而推送里
//    那句「参考止损 X」既没说它是 -3%，也没说它和账户实际执行的不是一回事 ——
//    用户照 -3% 手动离场，模拟盘却在 -8% 才动，系统自己跟自己对不上。
//    现在把这两层都摊开说：数值照旧（改它会波及全部历史文案），前提补上。
const STOP_REF_PCT = -3;
function stopRefOf(s) {
  if (!s || !(s.price > 0)) return '-';   // 缺价不许算出一个 0 或 NaN 混进文案
  const p = (s.price || 0) * (1 + STOP_REF_PCT / 100);
  return p > 0 ? p.toFixed(2) : '-';
}
// ⛔ 前提必须跟数值一起给出：这个 -3% 是**通用参考位**，不是你账户里那根止损线。
//    （holdings.js 导出的是工厂函数、没有 get()，所以直接读那份配置；60 秒缓存一次够用。）
let _stopRefCfg = { t: 0, v: -8 };
function stopRefNote() {
  const now = Date.now();
  if (now - _stopRefCfg.t > 60000) {
    try {
      const o = JSON.parse(fs.readFileSync(path.join(__dirname, 'holdings.json'), 'utf8'));
      if (o && typeof o.stopPct === 'number' && isFinite(o.stopPct)) _stopRefCfg = { t: now, v: o.stopPct };
      else _stopRefCfg = { t: now, v: _stopRefCfg.v };
    } catch { _stopRefCfg = { t: now, v: _stopRefCfg.v }; }
  }
  return `（现价${STOP_REF_PCT}%通用参考位；模拟盘按持仓页设置的 ${Math.abs(_stopRefCfg.v)}% 止损线执行）`;
}
// 强势信号判定：这类信号允许缩短去重窗口、重复推送
function isStrongAlert(a) {
  return a.type === '涨停'                                  // 已封板
    || ((a.prob || 0) >= 90)                                // 涨停概率极高
    || ((a.mainPct || 0) > 8);                              // 主力净占比极高（抢筹凶）
}
// ---------------- 盘中推送降噪：从「一命中就发」改成「攒一批、定时合并发一条」----------------
// 背景（2026-09-28 实盘首日实测）：主循环 5 秒一 tick，任何一批命中都立刻推送，
//   2 分钟内连发 5 条（10:09:41 / 10:10:35 / 10:10:52 / 10:11:17 / 10:11:22），手机被刷屏，
//   真正重要的那几条反而被淹没。
// 方案：命中先入缓冲区 → 到点合并成一条发出；每份只推最值得看的几只，其余留在面板实时看。
const INTRADAY = { buf: new Map(), timer: null, lastSent: 0, firstAt: 0, parts: [] };
// parts：hg 轮新增 —— 「盘中新增达标标的 / 趋势票」直推段的暂存队列。
// ⛔⛔ 病根（用户「重复推送的问题要改正」；线上实证 10-13 13:07:09 / 13:07:13 四秒连发两条
//    同标题「═══ 📊 量化看盘·盘中推送 ═══」）：主循环的涨停/大单/后排概率信号走
//    enqueueIntraday 缓冲（3 分钟间隔 + 攒批合并），而 scanTrendUniverse 里的
//    pool/trend 段是**直接 pushAll**，两条路径互不知晓 → 同一点上各发一条。
//    现在直推段也走这一条统一出口：同一节流、到点合并成一条。
const INTRADAY_MIN_GAP = 3 * 60 * 1000;   // 两份盘中快报最短间隔 3 分钟
const INTRADAY_MAX_WAIT = 60 * 1000;      // 命中后最多等 60 秒必发，保证时效
const INTRADAY_MAX_ITEMS = 4;             // 每份快报最多推 4 只
const ALERT_RANK = { '涨停': 0, '后排涨停概率': 1, '大单快速流入': 2, '趋势票': 3 };
function alertScore(a) {
  return (a.prob || 0) * 2 + (a.riseProb || 0) + (a.mainPct || 0) * 3 + (a.strong ? 30 : 0);
}
function enqueueIntraday(list) {
  for (const a of list) {
    const k = a.type + ':' + a.code;
    const old = INTRADAY.buf.get(k);
    if (!old) {
      INTRADAY.buf.set(k, a);
      if (!INTRADAY.firstAt) INTRADAY.firstAt = Date.now();
      continue;
    }
    // 同一窗口内重复命中：保留评分更高的那条，避免被后面一次弱信号覆盖掉
    if (alertScore(a) >= alertScore(old)) INTRADAY.buf.set(k, a);
  }
  if (INTRADAY.timer) return;
  const since = Date.now() - INTRADAY.lastSent;
  const wait = Math.max(5000, Math.min(INTRADAY_MAX_WAIT, INTRADAY_MIN_GAP - since));
  INTRADAY.timer = setTimeout(() => { INTRADAY.timer = null; flushIntraday(); }, wait);
  console.log('[盘中推送] 入队 ' + INTRADAY.buf.size + ' 条，' + Math.round(wait / 1000) + ' 秒后合并发出');
}
// hg 轮：盘中推送的【统一出口】—— 已拼好正文的消息段（趋势票/新增达标标的）也走同一条节流。
// 距上一份不足 3 分钟就入队等下一场 flush（与信号缓冲合并成一条），够距就直接发。
// ⛔ 这是 10-13「四秒连发两条盘中推送」的修法：直推段不再绕过 INTRADAY 自己发。
function enqueueIntradayMsg(text, opt) {
  const since = Date.now() - INTRADAY.lastSent;
  if (!INTRADAY.timer && since >= INTRADAY_MIN_GAP) {
    INTRADAY.lastSent = Date.now();
    pushAll(text, false, opt || {});
    return;
  }
  INTRADAY.parts.push({ text, opt: opt || {} });
  if (INTRADAY.timer) return;
  const wait = Math.max(5000, Math.min(INTRADAY_MAX_WAIT, INTRADAY_MIN_GAP - since));
  INTRADAY.timer = setTimeout(() => { INTRADAY.timer = null; flushIntraday(); }, wait);
  console.log('[盘中推送] 直推段入队，' + Math.round(wait / 1000) + ' 秒后与信号快报合并发出');
}
function flushIntraday() {
  const list = [...INTRADAY.buf.values()];
  const parts = INTRADAY.parts.splice(0);   // hg 轮：直推段与信号快报在同一场 flush 里合并
  const since = INTRADAY.firstAt;
  INTRADAY.buf.clear(); INTRADAY.firstAt = 0; INTRADAY.lastSent = Date.now();
  if (!list.length && !parts.length) return;
  // go 轮 A6：盘中预警汇总改私密（hg 轮起直推段也合并进这一条，private 统一在这里）；
  let msg = '', opt = { private: true };
  if (list.length) {
    list.sort((x, y) => (ALERT_RANK[x.type] ?? 9) - (ALERT_RANK[y.type] ?? 9) || alertScore(y) - alertScore(x));
    const top = list.slice(0, INTRADAY_MAX_ITEMS);
    opt.recommendationRows = freezeRecommendationRows(top, true);
    opt.newsRecommendationRows = freezeNewsRecommendationRows(top);
    // Persist only the exact signals included in this batch, never omitted rows.
    opt.signalRefs = top.map(a => ({ code: a.code, type: a.type, ts: a.ts, ...(/^[a-f0-9]{64}$/.test(a.signalId||'')?{signalId:a.signalId}:{}) }));
    // ⛔ 缓冲区是 (信号类型:代码) 键的 Map —— 同一只票在「涨停」与「大单流入」两个模块下各占一条。
    //    所以 list.length 是**信号条数**，不是股票只数；文案里那个"只"必须数去重后的代码。
    //    （旧写法直接把条数当只数报，命中 5 条里若有 1 只占两条，用户读到的是"共命中 5 只"—— 只有 4 只票。）
    const codesOf = arr => new Set(arr.map(a => a && a.code).filter(Boolean));
    const allCodes = codesOf(list), topCodes = codesOf(top);
    msg = buildAlertsReport(top, {
      total: list.length,                       // 条
      rest: list.length - top.length,           // 条
      codes: allCodes.size,                     // 只
      topCodes: topCodes.size,                  // 只
      restCodes: Math.max(0, allCodes.size - topCodes.size),  // 只：不在本份里的那些票
      since
    });
  }
  // hg 轮：直推段拼在同一条消息里（去掉它与快报重复的大标题），undo/modDay 合并——
  //    占位退还与模块配额回滚的语义一个都不少（见 pushAll 的 _release）。
  // ⛔ 顺带修掉一处渠道不一致：直推段原来没带 private（落群机器人），而「盘中推送」按
  //    用户 10-12 定的私密渠道白名单必须走私密通道；合并后统一 private。
  for (const p of parts) {
    const body = String(p.text || '').replace(/^═══ 📊 量化看盘·盘中推送 ═══\n?/, '');
    if (!body) continue;
    msg = msg ? msg + '\n' + body : body;
    if (p.opt && p.opt.undo) opt.undo = (opt.undo || []).concat(p.opt.undo);
    if (p.opt && Array.isArray(p.opt.recommendationRows)) opt.recommendationRows = (opt.recommendationRows || []).concat(p.opt.recommendationRows);
    if (p.opt && Array.isArray(p.opt.newsRecommendationRows)) opt.newsRecommendationRows = (opt.newsRecommendationRows || []).concat(p.opt.newsRecommendationRows);
    if (p.opt && p.opt.modDay) {
      const ms = Array.isArray(p.opt.modDay) ? p.opt.modDay : [p.opt.modDay];
      opt.modDay = (opt.modDay || []).concat(ms);
    }
  }
  if (!msg) return;
  pushAll(msg, false, opt);
}

function buildAlertsReport(list, opt) {
  const ORDER = ['涨停概率预警', '大单流入', '趋势票信号', '涨停封板'];
  const GROUP = { '后排涨停概率': '涨停概率预警', '大单快速流入': '大单流入', '趋势票': '趋势票信号', '涨停': '涨停封板' };
  const pct = v => `${(v || 0) >= 0 ? '+' : ''}${(v || 0).toFixed(2)}%`;
  // 强势信号会被重复推送，标上「第N次」让用户知道是加推而不是啰嗦
  const head = a => `${a.strong ? '🔥' : '▪'} ${a.name}(${a.code})`;
  const no = a => (a.pushNo && a.pushNo > 1) ? ` ·第${a.pushNo}次` : '';
  const probLine = a => (a.type === '涨停')
    ? `  🎯 已封板（不再预判上涨概率，重点防炸板）`
    // ⛔「上涨概率」赌的到底是"涨多少、多久"必须由它自己说：它被回验的口径是 sig.nd
    //    =【次日最高涨幅≥HIT_THR%】。只写"上涨概率"等于把结论给了、前提没给。
    : a.type === '后排涨停概率'
      ? `  🎯 ${probDef('ztToday')}模型估值 ${a.prob == null ? '-' : a.prob}%（未独立校准）`
      : `  🎯 ${probDef('up3Next')}模型估值 ${a.riseProb != null ? a.riseProb : '-'}%（未独立校准）`;
  const lines = ['═══ 📊 量化看盘·盘中推送 ═══'];
  for (const g of ORDER) {
    const items = list.filter(a => GROUP[a.type] === g);
    if (!items.length) continue;
    lines.push(`【${g}】`);
    for (const a of items) {
      // 统一三段式：上涨概率预判 → 选股逻辑 → 风险提示 + 参考止损（避免盲目追高造成损失）
      lines.push(
        `${head(a)} 现价${a.price} (${pct(a.pct)})${no(a)}`
        + (a.type === '后排涨停概率' ? ` 距涨停${a.gapPct != null ? a.gapPct + '%' : '-'}` : '')
        + `\n${probLine(a)}`
        + fuseLine(a)
        + `\n  📌 选股逻辑: ${a.logic || (a.msg || '').slice(0, 80)}`
        + `\n  ⚠️ ${a.risk || '暂无特殊风险'} | 参考止损 ${a.stopRef || '-'}${(a.stopRef && a.stopRef !== '-') ? stopRefNote() : ''}`
      );
    }
  }
  // 降噪说明：明确告诉用户「为什么只有这几条」，避免以为漏了
  // ⛔ 「只」= 股票只数（去重后的代码数），「条」= 信号条数（同票多模块各算一条）—— 两个量词不许混用。
  if (opt && opt.rest > 0) {
    const t = opt.since ? new Date(opt.since).toLocaleTimeString('zh-CN') : '';
    const _c = opt.codes != null ? opt.codes : new Set(list.map(a => a && a.code)).size;
    const _tc = opt.topCodes != null ? opt.topCodes : _c;
    const _rc = opt.restCodes != null ? opt.restCodes : Math.max(0, _c - _tc);
    lines.push(`\n（${t} 起共命中 ${_c} 只票 / ${opt.total} 条信号，按优先级推送最值得看的前 ${_tc} 只（${list.length} 条），其余 ${_rc} 只实时显示在面板，不占用推送）`);
  }
  const anyStrong = list.some(a => a.strong);
  lines.push(anyStrong
    ? '\n🔥=强势信号（封板/概率≥90/主力净占比>8）。'
    : '');
  lines.push('盘中快报每 3 分钟最多一条（命中后 60 秒内必发）；同股同信号 10 分钟内不重复。');
  lines.push('⚠️ 概率为模型预判，非投资建议；务必带止损，跌破参考位即离场。');
  return lines.join('\n');
}
// 学习进化自检：把「按融合胜率推的票」和「按模型原值推的票」的实测命中率摆在一起。
// 这是「你学的东西到底有没有用」唯一的量化答案 —— 不看口号，看同一批样本两套分档差多少。
function fusedEvoLine() {
  const r = learnFusedReport();
  if (!r.fusedN) return '';
  const head = `\n【历史分档对照】研究排序值已回验 ${r.fusedN} 条（次日最高涨≥${HIT_THR}%事件，非独立校准）`;
  const ok = r.rows.filter(x => x.lift != null);
  if (!ok.length) return head + '（分档样本还不够比较，继续积累中）';
  const avg = Math.round(ok.reduce((s, x) => s + x.lift, 0) / ok.length);
  return head + '：' + ok.map(x => `${x.bucket}档 原值${x.rawRate}%→学后${x.fusedRate}%(n=${x.fusedN})`).join('、')
    + `，平均${ppTxt(avg)}`
    + (avg > 0 ? ' —— 仅为同批历史样本分档差异' : avg < 0 ? ' —— ⚠️ 历史分档频率更低，需复查' : '');
}
// 每日复盘消息：定时推送与手动补发共用，避免两处逻辑走偏
// ⛔ 本轮（各池标的 · 上涨原因）：**所有池子都要带上涨原因，不只是精选池**
//    （用户原话：「不是只加精选池，是全加，包括复盘趋势池啥的」）。
//    每个池子用自己的原因字段，⛔ 不许拿别池的字段凑数（凑出来的原因看着有、其实是假的）：
//      精选池 = 选股逻辑 pathWhy / paths；      趋势池 = 趋势逻辑 why / flags；
//      大单池 = 主力资金合成（mainPct·净流入·位置·冷热 —— 大单池没有文案型原因字段，只能按资金口径合成）；
//      补涨池 = 补涨理由 reason。
//    全部按主线归并（sectorOfStock → themeOfSec），与涨停股同一套口径。抽成纯函数便于守门单测。
function poolReasonSection(pool, opt) {
  const _o = opt || {};
  const _pool = (pool || []).slice(0, _o.limit || 12);
  if (!_pool.length) return '';
  const _grp = {};
  for (const x of _pool) {
    const _sec = (typeof sectorOfStock === 'function') ? sectorOfStock({ code: x.code, name: x.name }) : (x.sector || '未知');
    const _th = (typeof themeOfSec === 'function') ? themeOfSec(_sec) : _sec;
    (_grp[_th] || (_grp[_th] = [])).push(x);
  }
  return Object.entries(_grp).sort((a, b) => b[1].length - a[1].length).map(([th, xs]) => {
    const _lines = xs.slice(0, 6).map(x => {
      const _why = (typeof _o.why === 'function') ? _o.why(x) : whySelected(x);
      const _extra = (typeof _o.extra === 'function') ? _o.extra(x) : '';
      const _p = Number(x.pct) || 0;
      return `▪ ${x.name}(${x.code}) 涨${(_p > 0 ? '+' : '')}${_p.toFixed(1)}%${_extra}${_why ? '\n  上涨原因: ' + String(_why).slice(0, 60) : ''}`;
    }).join('\n');
    return `【${th}】${xs.length}只\n${_lines}`;
  }).join('\n\n');
}
// 各池原因解析器（纯函数，供 poolReasonSection 与守门单测共用）
function whySelected(x) {
  return (x.pathWhy && Object.keys(x.pathWhy).length) ? Object.values(x.pathWhy).join('；') : (x.paths || []).join('、');
}
function whyTrend(x) { return x.why || (x.flags || []).filter(Boolean).join(' + ') || ''; }
function whyBigMoney(x) {
  const _b = [];
  if (x.mainPct != null) _b.push(`主力净占比${x.mainPct}%`);
  if (x.mainInflow) _b.push(`净流入${x.mainInflow >= 1e8 ? (x.mainInflow / 1e8).toFixed(1) + '亿' : Math.round(x.mainInflow / 1e4) + '万'}`);
  if (x.ctx && x.ctx.flowKind) _b.push(x.ctx.flowKind);
  if (x.heat && x.heat.cold) _b.push('板块偏冷');
  return _b.join(' · ');
}
function whyBuzhang(x) { return x.reason || ''; }

// ⛔⛔ 补涨池条目唯一读取入口（2026-10-09 fy 轮）
//    S.buzhang 历史上有「数组」与「{time, items, empty}」两种形态并存，而**写入端一律写对象形态**
//    （10224 / 10141 / 10155 三处都是 `S.buzhang = { time, items }`）。
//    于是任何按数组读的地方都会炸：实测 nextPlanUniverse 里 `(S.buzhang || []).forEach(...)`
//    → TypeError「(S.buzhang || []).forEach is not a function」→ **次日作战计划整个计算失败**
//    （日志铁证：[nextplan] 计算失败）。
//    ⛔ 这种「同一份数据在不同模块被当不同东西」已经踩了第二次（复盘里也各写了一份形态判断），
//    现在收成唯一入口：读补涨池条目一律 buzhangItems()，不许再各写一份 Array.isArray 判断。
function buzhangItems() {
  const b = S.buzhang;
  if (Array.isArray(b)) return b;
  return (b && b.items) || [];
}

function buildReviewMessage() {
  const it = (S.review && S.review.items) || [];
  // ⛔ 本轮：**所有池子**都带「上涨原因」（用户：不是只加精选池，是全加，包括复盘趋势池啥的）。
  //    涨停股本就有【关注度Top8】的归因，这里把其余四个池补齐，共用同一套主线归并口径。
  const _bz = buzhangItems();
  const _poolDefs = [
    ['选中的标的', S.candidatePool, whySelected, x => (x.score != null ? ' 评分' + x.score : ''), 12],
    ['趋势池', S.trendPool, whyTrend, x => (x.trendScore != null ? ' 趋势分' + x.trendScore : ''), 6],
    ['大单池', (S.bigMoney && S.bigMoney.items) || [], whyBigMoney, x => (x.prob != null ? ' 概率' + x.prob + '%' : ''), 6],
    ['补涨池', _bz, whyBuzhang, x => (x.prob != null ? ' 概率' + x.prob + '%' : ''), 6],
  ];
  const poolBlock = _poolDefs.map(d => {
    const _sec = poolReasonSection(d[1], { why: d[2], extra: d[3], limit: d[4] });
    return _sec ? `\n\n【${d[0]} · 上涨原因】\n${_sec}` : '';
  }).join('');
  // 命中率只报「实盘预测」口径（S.learn.samples 已在 recomputeBuckets 里替换成实盘数）。
  // 以前连历史回测样本一起报，等于拿"已知答案倒推"的成绩充门面，看不出真实水平。
  const _sp = S.learn.split;
  const _spLine = _sp ? `（其中历史回测 ${_sp.backtest.n} 个 ${_sp.backtest.rate}%、已涨停后登记 ${_sp.posthoc.n} 个，均不计入）` : '';
  const learnLine = S.learn.samples ? `\n\n【机器学习·实盘预测口径】累计信号${S.learn.samples}个 命中${S.learn.hits}个（${Math.round(S.learn.hits / S.learn.samples * 100)}%） 自适应评分线${S.learn.scoreThreshold}${_spLine}` : '';
  // ⛔ 与 items 同源：用复盘算好那一刻定格的快照，而不是推送时实时的 S.ztPool
  //    （旧 review.json 没有这两个字段时兜底实时值，行为与修之前一致）
  const _rvHead = (S.review && S.review.head) || (it.length ? todayHead() : '');
  const _rvZtN = (S.review && S.review.ztN != null) ? S.review.ztN : (S.ztPool || []).length;
  // 复盘是哪一天的必须跟着快照一起说（见 mkReviewShell 注释）：以前只写 HH:MM:SS，
  //    读回来的旧档会被当成"刚刚算的"。日期取快照自带的 date，缺了就老老实实不写。
  const _rvDate = ((S.review && S.review.date) || '').replace(/^(\d{4})(\d{2})(\d{2})$/, '$1-$2-$3');
  const tail = `\n复盘生成时间 ${_rvDate ? _rvDate + ' ' : ''}${(S.review && S.review.time) || '-'}（涨停池 ${_rvZtN} 只）${learnLine}${fusedEvoLine()}`;
  if (!it.length) return `═══ 📋 每日复盘 ═══\n今日无涨停个股可复盘${tail}`;
  const cnt = k => it.filter(x => x[k]).length;
  // ⛔ 本轮（fy）：把「同花顺涨停原因覆盖了多少只」也写进统计 —— 取不到时要让人一眼看见是取数问题，
  //    而不是以为系统压根没有这项数据（实测本地 69/69、线上 12/69，云端取同花顺被限流）。
  const stat = `形态统计: 站上5日线 ${cnt('aboveMa5')}只 · 破前高站稳 ${cnt('brokeHighHold')}只 · 量价齐升 ${cnt('volPriceUp')}只 | 首板${it.filter(x => !(x.limitUpCount > 1)).length}只 连板${it.filter(x => x.limitUpCount > 1).length}只 | 同花顺涨停原因 ${S.ztReasonHit || '-'}`;
  const top = it.slice(0, 8).map(x => {
    const shape = [x.aboveMa5 ? '站5日线' : null, x.brokeHighHold ? '破前高' : null, x.volPriceUp ? '量价齐升' : null].filter(Boolean).join('·') || '形态待定';
    // ⛔ 本轮（fy）：同花顺涨停原因一直【取到了却没显示】—— 旧文案只渲染 A.buildZTReason 合成的
    //    「【板块】…【封板】…」归因，用户看到的根本不是同花顺那条真实原因（"固态电池+铝塑膜"），
    //    于是就有了「同花顺里面不是有吗，怎么取不到」。现在显式打出来：
    //    ⛔ 取到就写同花顺原文；取不到就明说「未取到」，绝不拿合成归因冒充同花顺原因。
    const _ths = (x.themes && x.themes.length) ? x.themes.join('+') : (x.reasonRaw || '');
    const _thsLine = _ths ? `\n  涨停原因(同花顺): ${String(_ths).replace(/\s+/g, ' ').slice(0, 60)}` : '\n  涨停原因: 同花顺未取到';
    const reason = (x.reason || '').replace(/\s+/g, ' ').slice(0, 30);
    const seal = x.sealRatio != null ? `封板${Math.round(Math.min(x.sealRatio, 1.5) * 100)}%` : '';
    const brk = x.breakCount != null ? `开板${x.breakCount}次` : '';
    // ⚠️ peers 是 {n,lb,role,strong} 对象数组，直接 join 会变成 [object Object]
    const peers = (x.peers || []).length ? `\n  同板强势: ${(x.peers || []).map(p => typeof p === 'string' ? p : (p.role === 'leader' ? '🟥' : p.role === 'deputy' ? '🟧' : p.role === 'mid' ? '🟨' : '') + `${p.n}${p.lb > 1 ? `(${p.lb}板)` : ''}`).join('、')}` : '';
    return `▪ ${x.name}(${x.limitUpCount > 1 ? x.limitUpCount + '板' : '首板'}) ${probDef('ztNext')}概率${x.prob}% | ${shape} ${seal} ${brk}${_thsLine}${reason ? '\n  归因: ' + reason : ''}${peers}`;
  }).join('\n');
  return `═══ 📋 每日复盘 · 涨停形态与归因 ═══\n${_rvHead}${stat}\n\n【关注度Top8】\n${top}${poolBlock}\n完整复盘见面板${tail}`;
}

// ---------------- 次日作战计划（nextplan.js · 2026-10-01 正式挂载） ----------------
// 🔴 事故背景：nextplan.js 早在 2026-09-29 就写完了（文件头记着用户原话——"筛选第二天能干的票，
//    要附加选股逻辑和条件，把逻辑讲清楚，让他能看懂、能复盘、能自己上手"），但 server.js 里
//    从头到尾没有 require 它：无 API、无定时、无面板入口，等于躺在硬盘上三天一次都没跑过。
//    用户 2026-10-01 凌晨质问「为什么没推送今天涨停的票让我买」——系统推的是"复盘/归因"
//    （为什么涨停、封单多少），从来不是"明天买谁、多少钱进、跌到哪算错"。差的正是这一块。
// 定位区分：复盘 = 解释昨天；作战计划 = 安排明天（带进场/止损/失效条件/次日验证）。
S.nextplan = S.nextplan || { date: null, applyDate: null, time: null, plan: null, text: null, cand: 0, universeN: 0, missKline: 0 };

// 候选池：涨停池 + 补涨龙 + 大单池 + 趋势池，按 code 去重。
// 涨停股照样进池 —— 但 evaluate 内部对"当日涨停收盘"记 -14 分（次日高开一致性过强），
// 所以真能上榜的多是"温和走强/未涨停"的票，这正是我们要的：不追板，只做有逻辑的票。
function nextPlanUniverse() {
  const seen = new Set(); const out = [];
  // ⛔ 2026-10-08 修（用户问「次日作战计划迟迟不更新，那我要这个标签的意义在哪里」）：
  //    实测 42 只候选最高只有 36 分，55 分档与 45 分接力档全部归零 → 面板永远空着。
  //    病根之一：涨停池 S.ztPool 根本没有 mainInflow 字段，而 nextplan 的资金维度
  //    （fundOf，最高可加 24 分）**只认这一个字段** → 不补就是恒 0，且不报错不告警。
  //    现在从全A快照 S.stocks 补上；缺就给 undefined（让 fundOf 走「无数据」分支），
  //    ⛔ 绝不给 0 —— 0 会被当成「主力净流入为零」这个既成事实，比「没数据」更误导。
  const _npSnap = new Map((S.stocks || []).map(x => [x.code, x]));
  const add = (s, from) => {
    if (!s || !s.code || seen.has(s.code)) return;
    if (A.isJunkName(s.name)) return;
    if (capTooSmall(s)) return;   // lj：全模块<40亿不选
    seen.add(s.code);
    // ⚠️ 这些字段别漏：nextplan 只用前几个，但「十四条」要用 floatCap(①流通市值)、
    //    amount+sealAmount(⑧封成比)、breakCount(⑨是否硬板)、limitUpCount(⑪连板上限)。
    //    漏一个，对应那条就变成"缺数据"——看起来像系统不会算，实际是自己没传。
    const _sn = _npSnap.get(s.code);
    out.push({
      code: s.code, name: s.name, price: s.price, pct: s.pct, turnover: s.turnover,
      mainInflow: (s.mainInflow != null) ? s.mainInflow : (_sn ? _sn.mainInflow : undefined),
      from,
      reason: s.reason || '',   // ⛔ 供主线归并识别当日真实驱动（themeKeyOf 优先看 reason）
      limitUpCount: s.limitUpCount || 0, sealAmount: s.sealAmount || 0,
      floatCap: s.floatCap || 0, amount: s.amount || 0, breakCount: s.breakCount,
    });
  };
  (S.ztPool || []).forEach(s => add(s, '涨停'));
  // ⛔ 走唯一入口 buzhangItems()：写入端恒写对象形态，这里按数组读会 TypeError
  //    → nextPlanUniverse 整体抛错 → 次日作战计划一个字都出不来（不报错，只是"没计划"）。
  buzhangItems().forEach(s => add(s, '补涨'));
  ((S.bigMoney && S.bigMoney.items) || []).forEach(s => add(s, '大单'));
  (S.trendPool || []).forEach(s => add(s, '趋势'));
  return out;
}

async function computeNextPlan(limitN) {
  const cands = nextPlanUniverse().slice(0, limitN || 80);
  if (!cands.length) {
    // ⛔ 同上：候选池为空若是因为行情源没回来，别把上一版的作战计划抹成"候选池为空"
    if (marketReady()) { S.nextplan = { date: NP.localDate(), time: new Date().toLocaleTimeString('zh-CN'), plan: null, text: null, cand: 0, universeN: 0, missKline: 0, empty: emptyWhyOf('noCand') }; staleMark('nextplan', 'empty'); }
    else staleMark('nextplan', 'held');
    return S.nextplan;
  }
  // K线是硬门槛（techOf 要 25 根）：内存 → 磁盘缓存 → 网络补拉，并发 8 避免拖死网关
  const built = await em.pool(cands, async c => {
    const rows = await klineRows(c.code);
    if (!rows || rows.length < 25) return null;
    const secName = (c.sector && c.sector !== '未知') ? c.sector : sectorOfStock({ code: c.code, name: c.name });
    const sec = (S.sectors || []).find(x => x.name === secName);
    // ⛔ 2026-10-08 修：与板块强度同一个病根 —— S.sectors 是东财BK涨幅榜（固态电池BK0968／钠离子电池BK0988…），
    //    secName 是 ztPool 的题材名（电力设备／电池／电池技术…），两套命名 20 个里只有 2 个能对上 →
    //    sec 恒为 null → 板块涨幅(最多+6) 与 板块资金(+4) 恒为 0，每只票凭空少 10 分；
    //    叠加上面补掉的 mainInflow 缺失（最多+24），42 只候选实测最高只有 36 分 →
    //    55 分档与 45 分接力档双双归零 → 面板「次日作战计划」永远空着（用户原话：那我要这个标签的意义在哪里）。
    //    现在涨停家数与板块资金改走主线归并的可靠数据（电池主线 12 只而不是「电池」这 1 只）；
    //    板块涨幅能对上就用，对不上承认缺失（中性 0，⛔ 不倒扣也不伪造）。
    const _ts = themeStrengthOf({ sector: secName, reason: c.reason || '' });
    const sector = (secName && secName !== '未知') ? {
      name: _ts.theme || secName,
      ztCount: (_ts.sectorZT > 0) ? _ts.sectorZT : (((S.ztBySector || {})[secName] || []).length),
      pct: sec ? +sec.pct || 0 : 0,
      mainInflow: _ts.inflowSum || 0,
    } : null;
    const fd = (S.fundDays && S.fundDays.get) ? (S.fundDays.get(c.code) || []) : [];
    return {
      stock: { ...reviewSnapshotFields(c), code: c.code, name: c.name, price: c.price, pct: c.pct, turnover: c.turnover, mainInflow: c.mainInflow },
      rows, sector, fundDays: fd, elapsedMin: 240,
    };
  }, 8);
  const universe = built.filter(u => u && reviewRecommendation({...u.stock,...researchQuoteFields(u.stock)}, 'dated-observation').canObserve);
  const plan = NP.buildPlan(universe, { maxPicks: 6, minScore: 55 });
  // 标出来路（涨停/补涨/大单/趋势）：同一只分不清来源，用户没法判断该信哪条逻辑
  const candMap = new Map(cands.map(c => [c.code, c]));
  for (const p of (plan.picked || [])) p.from = (candMap.get(p.code) || {}).from || null;

  // ⚡ 涨停接力单独成段 —— 用户要的就是"今天涨停的票，明天能不能干"。
  //    但 evaluate 对"当日涨停收盘"硬扣 14 分（次日高开一致性过强，接力是负期望动作），
  //    55 分门槛下涨停票几乎全军覆没（实测 9/30 的 52 只最高 48 分）。
  //    全军覆没 = 用户根本看不到涨停票，等于没回答他的问题。所以这里用 45 分单独列一段，
  //    并明确写成「高风险·要盯盘才做」：不是推荐追板，是把接力的前置条件摆在他面前。
  const ztCodes = new Set(cands.filter(c => c.from === '涨停').map(c => c.code));
  const relayRaw = NP.buildPlan(universe.filter(u => ztCodes.has(u.stock.code)), { maxPicks: 4, minScore: 45, allowLimitUp: true });   // lc：接力通道放行涨停票（主推已 drop）
  const relay = (relayRaw.picked || []).map(x => {
    const c = candMap.get(x.code) || {};
    return { code: x.code, name: x.name, price: x.price, score: x.score, grade: x.grade, sector: x.sector,
      limitUpCount: c.limitUpCount || 0, sealAmount: c.sealAmount || 0,
      entry: x.entry, stop: x.stop, target: x.target,
      reason: (x.reasons || [])[0] || '', risk: (x.risks || [])[0] || '', confirm: (x.confirm || []).slice(0, 2) };
  });
  // ⛔ 适用日必须在排版之前注入 plan —— NP.formatPlan(plan) 会把这个日期写进正文首行。
  //    plan.date 是【生成日】（今天），适用日是下一个交易日（可能是下周甚至节后）。
  const _applyDate = nextTradeDay() || '下一交易日';
  plan.applyDate = _applyDate;
  S.nextplan = {
    date: plan.date, applyDate: _applyDate, time: new Date().toLocaleTimeString('zh-CN'),
    plan, text: NP.formatPlan(plan), relay,
    cand: cands.length, universeN: universe.length, missKline: cands.length - universe.length,
  };
  staleMark('nextplan', 'fresh');
  console.log(`[nextplan] 候选${cands.length} → K线充足${universe.length} → 主推${(plan.picked || []).length} → 涨停接力${relay.length}`);
  return S.nextplan;
}

// ── 用户的「十四条」选股体系（2026-10-01）────────────────────────
// 用户原话：「我要的从来都不是票，是你能否提前发现那些能涨停、而且我买了以后会盈利、同时还能规避风险」。
// 这套规则是他自己的尺子，所以：逐条单独判并输出数值与计算式（不给说不清的总分）；
// 算不出的一律标「缺数据」而不是「不符合」（没数据≠不满足，这个坑踩过多次）；
// ⑦⑫⑭ 依赖竞价分时/龙虎榜，暂无数据源，明确挂起而不是假装判过。
S.myrules = S.myrules || { date: null, time: null, count: 0, scanned: 0, items: [], all: [] };

// ⑫ 龙虎榜（东财）缓存。
// ⚠️ 两个坑，都是实测出来的：
//   ① 龙虎榜【收盘后约18:00】才公布：盘中拉当日 = 拉到空表 → 整片变"缺数据"，等于白接。
//      所以 18 点前必须回退到上一个交易日（用K线倒数第二根，自动跳过周末与节假日）。
//   ② 一次扫描要打 6 页东财接口，不缓存就是每分钟打一次 → 限流后整条链路哑掉。故缓存 30 分钟。
// 「涨停原因/题材」缓存（同花顺涨停池，实测 9/30 是 52/52 全覆盖）。
// 用途：让每一只涨停票都能说清"因为什么涨"，而不是只丢一个代码和一个涨幅 ——
//   用户 2026-10-01 原话质问过「你分析基本面以及涨停逻辑了吗」，这就是那块的答案。
// 缓存 10 分钟：同花顺对高频请求会限流，而题材在盘中变化没那么快。
// ⛔ 缓存里要存**两个**日期，不能只存一个（2026-10-06 修，本轮新角度：缓存与失效）：
//   forDay = 这次是为哪个「目标交易日」拉的（命中键，与下面的 d0 比）
//   used   = 回退之后**实际**取到的是哪天的数据（仅用于诊断与决定 TTL）
//   以前只存一个 date、写的是 used、读的时候却和 d0 比 —— 一旦走上回退分支
//   （早盘当天池子还没出、节假日、接口延迟），used 就变成 d0-1…d0-4，永远 ≠ d0
//   → **缓存永不命中** → 每 8 分钟重跑一遍最多 5 次网络请求。
//   而这段缓存存在的唯一理由就是「同花顺对高频请求会限流」，等于最该生效的时候恰恰失效。
let _ztReasonCache = { forDay: '', used: '', t: 0, ttl: 0, map: null };
// 日期加减（YYYYMMDD ± n 天）
function shiftDate(yyyymmdd, n) {
  const s = String(yyyymmdd).replace(/-/g, '');
  const d = new Date(+s.slice(0, 4), +s.slice(4, 6) - 1, +s.slice(6, 8));
  d.setDate(d.getDate() + n);
  return `${d.getFullYear()}${String(d.getMonth() + 1).padStart(2, '0')}${String(d.getDate()).padStart(2, '0')}`;
}
async function ztReasonCached() {
  // ⚠️ 不能用 lastTradeDay()（机器日期，只跳周末不跳节假日）：
  //    实测 10/1 国庆凌晨上线后，它给出 20261001 → 同花顺那天根本没有涨停池 → 题材 0/52，
  //    而涨停池本身是 9/30 的 52 只。日期对不上就是整片空。必须按【数据真实最新日】取。
  let base = null;
  try { base = await dataTradeDay(); } catch {}
  const d0 = String(base || lastTradeDay()).replace(/-/g, '');
  if (_ztReasonCache.map && _ztReasonCache.forDay === d0 && Date.now() - _ztReasonCache.t < _ztReasonCache.ttl) {
    return _ztReasonCache.map;
  }
  // 再逐级回退：节假日/接口延迟时当天池子可能是空的，最多往前找 5 天
  let map = new Map(), used = d0;
  for (let back = 0; back < 5 && !map.size; back++) {
    const d = shiftDate(d0, -back);
    try { map = await em.fetchZtReason(d); } catch (e) { console.error('[myrules] 涨停原因拉取失败:', d, e && e.message); }
    if (map.size) used = d;
  }
  if (!map.size && _ztReasonCache.map) return _ztReasonCache.map;   // 全拉空时沿用上次，别把已有题材抹掉
  // 命中键记目标日 d0（不是 used），否则回退一次之后缓存就再也命中不了。
  // 回退来的数据是"借前几天的话题"，寿命给短一点，别把当天新出的池子压着 10 分钟不放。
  const ttl = (used === d0) ? 10 * 60 * 1000 : 90 * 1000;
  _ztReasonCache = { forDay: d0, used, t: Date.now(), ttl, map };
  return map;
}
// 把 "电力人工智能+能源数字化+股份划转完成" 拆成题材词并统计热度
function ztTopics(zt, topN) {
  const m = {};
  for (const z of zt) {
    for (const t of String(z.reason || '').split(/[+＋、,，]/)) {
      const k = t.trim();
      if (k && k.length <= 12) m[k] = (m[k] || 0) + 1;
    }
  }
  return Object.entries(m).sort((a, b) => b[1] - a[1]).slice(0, topN || 6);
}

const LHB_PUBLISH_HOUR = 18;
let _lhbCache = { date: '', t: 0, map: null };
async function lhbMapCached() {
  const now = Date.now();
  if (_lhbCache.map && now - _lhbCache.t < 30 * 60 * 1000) return _lhbCache.map;
  let d = null;
  try { d = await dataTradeDay(); } catch {}
  // ⚠️ 只有"数据日就是今天 且 还没到公布时间"才回退。
  //    不加"就是今天"这个条件的话，节假日/次日凌晨会把本已公布好的上一交易日榜
  //    再往前退一天（实测 10/1 凌晨会退到 9/29，白白丢掉 9/30 的完整榜单）。
  const n0 = new Date();
  const todayStr = `${n0.getFullYear()}-${String(n0.getMonth() + 1).padStart(2, '0')}-${String(n0.getDate()).padStart(2, '0')}`;
  if (d && d === todayStr && n0.getHours() < LHB_PUBLISH_HOUR) {
    try {
      const k = await em.fetchKline('000001', 6);
      if (k && k.rows && k.rows.length >= 2) d = String(k.rows[k.rows.length - 2].date).slice(0, 10);
    } catch {}
  }
  const map = d ? await em.fetchLhb(d) : new Map();
  // ⛔ t 必须取「写缓存这一刻」而不是函数开头那个 now（2026-10-06 修）：
  //    上面隔着三次 await（dataTradeDay / fetchKline / fetchLhb），慢的时候几十秒，
  //    用开头的时间戳等于把 30 分钟 TTL 的起点提前到请求发出前，数据到手时已经"老"了。
  _lhbCache = { date: d || '', t: Date.now(), map };
  return map;
}

async function computeMyRules(limitN) {
  const cands = nextPlanUniverse().slice(0, limitN || 120);
  if (!cands.length) {
    // ⛔ 同上：数据源没回来时保留上一次的自定义规则结果，别显示"候选池为空"
    if (marketReady()) { S.myrules = { date: NP.localDate(), time: new Date().toLocaleTimeString('zh-CN'), count: 0, scanned: 0, items: [], all: [], empty: emptyWhyOf('noCand') }; staleMark('myrules', 'empty'); }
    else staleMark('myrules', 'held');
    return S.myrules;
  }
  // 竞价快照只在 9:15~9:25 有，其它时段天然没有 → ⑥⑧ 会标「缺数据」，这是对的
  const aucMap = new Map();
  for (const s of ((S.auction && S.auction.strong) || [])) if (s && s.code) aucMap.set(s.code, s);
  // ⑫ 龙虎榜（东财）+ 涨停原因（同花顺）。
  // ⚠️ 龙虎榜收盘后才公布 → 拉【最近一个已公布交易日】的榜；盘中拉当日会拿到空表，
  //    那就整片变"缺数据"，等于白接。缓存 30 分钟，别每分钟打一次东财。
  let lhbMap = new Map();
  try { lhbMap = await lhbMapCached(); } catch (e) { console.error('[myrules] 龙虎榜拉取失败:', e && e.message); }
  const built = await em.pool(cands, async c => {
    const rows = await klineRows(c.code);
    if (!rows || rows.length < 60) return null;   // ③⑩⑬ 都要 60 根以上才判得准
    const secName = (c.sector && c.sector !== '未知') ? c.sector : sectorOfStock({ code: c.code, name: c.name });
    const sec = (S.sectors || []).find(x => x.name === secName);
    const sector = (secName && secName !== '未知') ? {
      name: secName, ztCount: ((S.ztBySector || {})[secName] || []).length,
      pct: sec ? +sec.pct || 0 : 0, mainInflow: sec ? +sec.mainInflow || 0 : 0,
    } : null;
    let pr = null;
    try { pr = A.calcProfitRatio(rows); } catch {}
    const au = aucMap.get(c.code);
    let ticks = null;
    try { ticks = await auctionTicksFor(c.code); } catch (e) { console.error('[myrules] 竞价分时拉取失败 ' + c.code + ':', e && e.message); }
    return {
      stock: {
        code: c.code, name: c.name, price: c.price, pct: c.pct, floatCap: c.floatCap,
        amount: c.amount, sealAmount: c.sealAmount, limitUpCount: c.limitUpCount, breakCount: c.breakCount,
        preClose: c.preClose,
      },
      rows, sector,
      auction: au ? { auctionAmount: au.auctionAmount, auctionPct: au.auctionPct } : null,
      profitRatio: pr,
      lhb: lhbMap.get(c.code) || null,
      aucTicks: ticks,
    };
  }, 8);
  const list = built.filter(Boolean);
  const r = MYRULES.scan(list, {});
  S.myrules = {
    date: NP.localDate(), time: new Date().toLocaleTimeString('zh-CN'),
    count: r.count, scanned: list.length,
    items: r.all.filter(x => x.pass).slice(0, 12),
    all: r.all.slice(0, 30),
  };
  staleMark('myrules', 'fresh');
  console.log(`[myrules] 扫描 ${cands.length} → K线充足 ${list.length} → 符合十四条 ${r.count} 只`);
  return S.myrules;
}

// 竞价分时缓存（按日）：⑦⑭ 用。东财限流时 fetchAuctionTicks 会抛错 → 失败不缓存（15 分钟内重试），
// 避免把"限流没拉到"永久当成"缺数据"（那样 ⑦⑭ 整片变 unknown）。
async function auctionTicksFor(code) {
  const cache = S.auctionTicks || (S.auctionTicks = {});
  const ds = NP.localDate();
  const hit = cache[code];
  // ⛔⛔ 2026-10-29 修（失败缓存无 TTL → 竞价窗内首次失败=当日全灭）：
  //    旧写法 `if (hit && hit.date === ds) return hit.ok ? hit.data : null;` 排在 failAt 判据**之前**，
  //    而同一天失败必定 hit.date === ds → 后面那条 15 分钟重试窗**永远走不到**（死代码）。
  //    实测后果：9:20(phase 2) 那一轮只要有一只票拉分时失败，本轮缓存就锁死成 null，
  //    9:25~9:30 唯一可信的那次抓取直接被判「分时不取 → 撤单陷阱判不出」，
  //    当日 auction_log 里 ticks 全 null（10-28、10-29 连续两天实证）。
  //    现在按 failAt 真 TTL 重试：成败都只在窗内静默，不额外加请求量。
  if (hit && hit.date === ds) {
    if (hit.ok) return hit.data;
    if (hit.failAt && Date.now() - hit.failAt < 15 * 60 * 1000) return null;
  }
  try {
    const d = await em.fetchAuctionTicks(code);
    cache[code] = { date: ds, ok: !!d, data: d, failAt: d ? 0 : Date.now() };
    return d;
  } catch (e) {
    cache[code] = { date: ds, ok: false, data: null, failAt: Date.now() };
    return null;
  }
}

// ═══ ①-4 竞价复盘 · 信号留档 + 次日K线归因 ═══
// 每天 9:25 后把竞价强势票快照（含竞价分时）落盘，供「竞价复盘」UI 把
// 「竞价分时 + 次日K线」同屏，把"竞价命中率退化"做成可视化复盘。
// ⛔ 只增量追加、按 date+code 去重；不覆盖历史。文件是运行时数据，.gitignore 已拦。
// ⛔⛔ dz+ 轮（决策表 D2）：这份留档原来是**易失**的 —— _publish.py 的 DATA_FILES 不含它，
//    而线上容器一天回收多次，手机端读线上副本就只剩「本容器启动后 9:25 写的当天几条」，
//    本机 108 条历史从未上云，#290 的聚合头在手机上等于白做。
//    现在三件事一起做（与 pushlog 同款，那套已在线上验证过）：
//      ① auction_log.json 进发布包（本机常驻=权威源，历史随发布上云）；
//      ② 每次落盘同时镜像到 durable/auction_log.json（主文件被误删/写坏时的最后一道）；
//      ③ 启动时把主文件与 durable 副本**合并去重**（键 date|code），不整文件覆盖。
const AUCTION_LOG_FILE = path.join(__dirname, 'auction_log.json');
const AUCTION_DURABLE_FILE = path.join(__dirname, 'durable', 'auction_log.json');
let _auctionLog = null;
// 竞价留档去重键：一天一只票一条（同一天重复抓到同一只票只留第一条）
function auctionLogKey(r) { return String((r && r.date) || '') + '|' + String((r && r.code) || ''); }
// 合并两份留档：键去重 + 按 date 升序（同日内保持原插入顺序，V8 sort 稳定）+ 裁到 cap。
// ⛔ 缺 date/code 的记录直接丢弃并不计数 —— 半条记录进不了任何统计，留着只会污染去重键。
function mergeAuctionLogs(existing, incoming, cap) {
  const seen = new Set(), out = [];
  for (const r of [...(Array.isArray(existing) ? existing : []), ...(Array.isArray(incoming) ? incoming : [])]) {
    if (!r || !r.code || !r.date) continue;
    const k = auctionLogKey(r);
    if (seen.has(k)) continue;
    seen.add(k); out.push(r);
  }
  out.sort((a, b) => String(a.date).localeCompare(String(b.date)));
  const c = typeof cap === 'number' ? cap : 1500;
  if (out.length > c) out.length = c;
  return out;
}
function loadAuctionLog() {
  if (_auctionLog) return _auctionLog;
  const file = readJsonSafe(AUCTION_LOG_FILE, 'auction_log.json（竞价信号留档·供复盘）');
  const dur = readJsonSafe(AUCTION_DURABLE_FILE, 'durable/auction_log.json（竞价留档本地耐久副本）');
  const base = Array.isArray(file) ? file : [];
  const merged = mergeAuctionLogs(base, dur, 1500);
  _auctionLog = merged;
  // 合并出增量就落盘一次：否则 durable 与主文件会一直分叉，下次启动又要重算，
  // 而且「恢复了 N 条」这件事只活在内存里（§10 教训：改内存≠改磁盘）。
  if (merged.length > base.length) {
    try { saveAuctionLog(); console.log('[durable] 竞价留档启动合并：' + base.length + ' → ' + merged.length + ' 条'); } catch (e) {}
  }
  return _auctionLog;
}
function mirrorAuctionDurable() {
  try {
    const dir = path.join(__dirname, 'durable');
    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
    atomicWrite(AUCTION_DURABLE_FILE, JSON.stringify(_auctionLog || []));  // ⛔ 不裁容量：durable 存全量
  } catch (e) { console.error('[durable] 竞价留档镜像失败（本地耐久降级，不影响主流程）:', (e && e.message) || e); }
}
function saveAuctionLog() {
  const _o = atomicWrite(AUCTION_LOG_FILE, JSON.stringify(_auctionLog));
  mirrorAuctionDurable();
  return _o ? true : _diskFail(AUCTION_LOG_FILE);
}
// captureAuction 跑完（已算分/概率）后调用：把本轮强势票写入留档。tickMap 是本轮补拉的竞价分时（仅 _ph>=2 才有）。
function logAuctionSignals(tickMap) {
  try {
    const au = S.auction;
    if (!au || !au.strong || !au.strong.length) return;
    const ds = (au.date && /^\d{8}$/.test(au.date)) ? au.date : ((typeof todayStr === 'function') ? todayStr() : '');
    if (!ds) return;
    const log = loadAuctionLog();
    const seen = new Set(log.map(r => r.date + '|' + r.code));
    const ztMap = au.ztProbMap || {};
    const _up = (S.breadth && typeof S.breadth.upRatio === 'number') ? S.breadth.upRatio : null;
    let added = 0;
    // lz：次强档一并留档（tier:'sub'，不推送不干扰强势口径，专供漏网学习）
    const _strongCodes = new Set((au.strong || []).map(s => s.code));
    const _subList = (au.subStrong || []).filter(x => x && x.code && !_strongCodes.has(x.code));
    for (const x of _subList) {
      if (seen.has(ds + '|' + x.code)) continue;
      log.push({ date: ds, code: x.code, name: x.name, auctionPct: x.auctionPct, floatCap: x.floatCap || 0,
        mainInflow: x.mainInflow || 0, score: null, tier: 'sub', why: ['次强档：竞价温和高开留档（漏网学习）'], ticks: null });
      seen.add(ds + '|' + x.code); added++;
    }
    for (const x of au.strong) {
      if (seen.has(ds + '|' + x.code)) continue;
      const tk = (tickMap && tickMap.get(x.code)) || null;
      const rec = {
        date: ds, code: x.code, name: x.name,
        auctionPct: x.auctionPct, floatCap: x.floatCap || 0, mainInflow: x.mainInflow || 0,
        score: x.score, trap: !!x.trap, trapWhy: x.trapWhy || '',
        why: x.why || [], risk: x.risk || [], factors: x.factors || [],
        prob: (ztMap[x.code] && ztMap[x.code].prob) || null,
        mktUpRatio: _up,
        ticks: (tk && tk.bars && tk.bars.length)
          ? { preClose: tk.preClose, bars: tk.bars.map(b => ({ t: b.t, price: b.price, high: b.high, low: b.low, volume: b.volume })) }
          : null,
      };
      log.push(rec); added++;
    }
    if (added) {
      if (log.length > 1500) log.splice(0, log.length - 1500);
      saveAuctionLog();
      console.log(`[auction] 竞价信号留档 +${added} 条（累计 ${log.length}）`);
    }
  } catch (e) { console.error('[auction] 信号留档失败:', (e && e.message) || e); }
}
// 次日结果（nd 口径，与回测一致：看次日最高价是否触板 / 达+3% / 收涨）：纯函数，便于单测。
// rows 为 klineRows 返回的日K（按日期升序）。判不出一律走 pending（不硬判为失败）。
function computeNdOutcome(rows, dateStr, code, name) {
  if (!rows || !rows.length) return { pending: true, reason: '无K线' };
  const d = String(dateStr).replace(/-/g, '');
  const di = rows.findIndex(r => String(r.date).replace(/-/g, '') === d);
  if (di < 0) return { pending: true, reason: '信号日无K线' };
  // ⛔⛔ dz+ 轮（决策表 D3）：**当日封板**必须先算出来，不能塞在「次日K线」之后。
  //    prob 预测的是「信号日当天封板」（§8bis 实证），而次日结果在 T+1 收盘前根本不存在 ——
  //    原来 pending 提前 return，等于 prob 永远等不到同口径的检验，面板只能拿
  //    「次日最高≥3%」去对「当日封板」的预测，这就是 §8bis 记录的口径错配。
  //    涨停价用 G1 轮定的**严口径**：round(前收 × (1+limitPct/100), 2)，
  //    ⛔ 不用宽口径 isLimitUp —— 它会把「触板后收在板下 1 分钱」算成封板（300006 实证）。
  //    ⛔ 前收缺失 → sameDayLimit=null（判不出就不判，不给 false 也不给 true）。
  let limitPct = 10;
  try { const v = Number(A.limitPctOf(code, name)); if (isFinite(v) && v > 0) limitPct = v; } catch (e) {}
  const sigClose = Number(rows[di].close) || 0;
  const sigPre = di > 0 ? (Number(rows[di - 1].close) || 0) : 0;
  const limPx = sigPre > 0 ? Math.round(sigPre * (1 + limitPct / 100) * 100) / 100 : null;
  const sameDay = {
    sigClose: sigClose || null,
    sigPre: sigPre || null,
    limitPx: limPx,
    sameDayLimit: (limPx == null || !sigClose) ? null : (sigClose >= limPx - 1e-9),
    sameDayPct: (sigPre > 0 && sigClose) ? (sigClose / sigPre - 1) : null,
  };
  const nx = rows[di + 1];
  if (!nx) return Object.assign({ pending: true, reason: '次日K线未生成（T+1 收盘后可见）' }, sameDay);
  const pre = sigClose;
  if (!pre) return Object.assign({ pending: true, reason: '信号日收盘缺失' }, sameDay);
  const open = Number(nx.open) || 0, high = Number(nx.high) || 0, low = Number(nx.low) || 0, close = Number(nx.close) || 0;
  const openGap = (open / pre - 1), highPct = (high / pre - 1), lowPct = (low / pre - 1), closePct = (close / pre - 1);
  const nd_limit = highPct >= (limitPct / 100) - 1e-9;   // 次日最高价触板（nd 口径核心；limitPct 是百分比，highPct 是小数，需同单位）
  const nd_p3 = highPct >= 0.03;                  // 次日最高 ≥ +3%
  const closeUp = closePct > 0;
  return Object.assign({ pending: false, date: String(nx.date).replace(/-/g, ''), open, high, low, close, volume: nx.volume, openGap, highPct, lowPct, closePct, limitPct, nd_limit, nd_p3, closeUp }, sameDay);
}
async function auctionNextDayOutcome(code, name, dateStr) {
  try { const rows = await klineRows(code); return computeNdOutcome(rows, dateStr, code, name); }
  catch (e) { return { pending: true, reason: (e && e.message) || '计算失败' }; }
}

function nextPlanNewsOptions(){
  const np=S.nextplan||{},rows=[...(Array.isArray(np.plan?.picked)?np.plan.picked:[]),...(Array.isArray(np.relay)?np.relay:[])];
  return rows.length?newsRecommendationSendOptions(rows,{private:true}):{private:true};
}
function buildNextPlanMessage() {
  const np = S.nextplan || {};
  const p = np.plan;
  // ⛔ 标题写【适用日】不写生成日（见 nextTradeDay 注释）：这份计划是给下一个交易日用的。
  //    生成日保留在尾部"生成于 …"，两个日期各自说清楚，不再让一个日期同时代表两件事。
  const _ad = np.applyDate || (p && p.applyDate) || '';
  const _gd = np.date || (p && p.date) || '';
  const tail = `\n生成于 ${_gd || '-'} ${np.time || '-'} · 适用于 ${_ad || '下一交易日'}（候选${np.cand || 0}只 · K线充足${np.universeN || 0}只${np.missKline ? ` · 缺K线${np.missKline}只` : ''}）`;
  const body = (p && p.picked && p.picked.length)
    ? NP.formatPlan(p)
    : `今日无可操作标的：候选 ${np.cand || 0} 只里没有一只达到 55 分门槛。\n宁可空仓，也不凑数。`;
  const relay = (np.relay || []).length ? '\n' + relaySection(np.relay) : '';
  return `═══ 🗓️ 次日作战计划 · ${_ad || '下一交易日'} ═══\n研究条件场景；价位为生成时输入，适用日现价与成交资格须重新核实。\n${body}${relay}${tail}`;
}

// 涨停接力段：把"今天封板的票明天能不能接力"摆出来，但条件必须先行。
// 写法上刻意不写成推荐 —— 每只都带"做不到就别碰"的确认条件。
function relaySection(list) {
  const L = ['⚡ 涨停接力（高风险 · 只在你能盯盘时做）', '以下今日已封板，纪律分已扣；不是推荐追板，是把接力的前置条件摆清楚：'];
  for (const x of list) {
    const lb = x.limitUpCount > 1 ? `${x.limitUpCount}连板` : '首板';
    const seal = x.sealAmount ? `封单${(x.sealAmount / 1e8).toFixed(1)}亿` : '';
    L.push(`▌${x.name}(${x.code}) ${x.price}元 ${lb}${seal ? ' · ' + seal : ''} · ${x.score}分`);
    L.push(`  进场 ${x.entry ? x.entry[0] + '~' + x.entry[1] : '-'} · 止损 ${x.stop} · 目标 ${x.target}`);
    if (x.reason) L.push(`  依据: ${x.reason}`);
    if (x.risk) L.push(`  ⚠️ ${x.risk}`);
    for (const c of (x.confirm || [])) L.push(`  ✔ 做不到就别碰: ${c}`);
  }
  return L.join('\n');
}

// 「今天涨停了什么」一句话总览：连板梯队 + 主线板块 + 封单最强。
// 用户原话：「涨停那么多你没有推送我」——以往只推 Top8 好标的，从不告知当日涨停全貌，
// 于是几十只涨停在系统眼里"存在却没说"。这一段把全貌摆在最前面。
function todayHead() {
  try {
    const ztAll = S.ztPool || [];
    if (!ztAll.length) return '';
    const lb = {};
    for (const z of ztAll) {
      const n = (z.limitUpCount || 0) > 1 ? (z.limitUpCount + '板') : '首板';
      lb[n] = (lb[n] || 0) + 1;
    }
    const ladders = ['8板', '7板', '6板', '5板', '4板', '3板', '2板', '首板']
      .filter(k => lb[k]).map(k => `${k} ${lb[k]}只`);
    let head = `今日涨停 ${ztAll.length} 只${ladders.length ? '｜' + ladders.join(' · ') : ''}\n`;
    // 最高板代表妖股（连板≥3，最多列3只）
    const hi = ztAll.filter(z => (z.limitUpCount || 0) >= 3)
      .sort((a, b) => (b.limitUpCount || 0) - (a.limitUpCount || 0)).slice(0, 3);
    if (hi.length) head += `最高板: ${hi.map(x => `${x.name} ${x.limitUpCount}板`).join('、')}\n`;
    // 主线板块（板块涨停潮 = 当天资金主线）
    const ml = (S.mainline && S.mainline.items) || [];
    if (ml.length) {
      head += `【主线板块】${ml.slice(0, 4).map(m => `${m.sector} ${m.count}只${m.maxLb > 1 ? '(最高' + m.maxLb + '板)' : ''}`).join('、')}\n`;
    }
    // 涨停题材（同花顺涨停原因聚合，只列 ≥2 只的：单只不算"题材"，那是个股独立事件）
    // → 直接回答"今天到底在炒什么"，也是用户问的"涨停逻辑"最直观的那一层
    const tp = (S.ztTopics || []).filter(x => x[1] >= 2);
    if (tp.length) {
      head += `【涨停题材】${tp.slice(0, 5).map(x => `${x[0]} ${x[1]}只`).join('、')}\n`;
    }
    // 封单最强（资金认可度最高的三只）
    const seal = ztAll.filter(z => (z.sealAmount || 0) > 0)
      .sort((a, b) => (b.sealAmount || 0) - (a.sealAmount || 0)).slice(0, 3);
    if (seal.length) {
      const inf = v => v >= 1e8 ? (v / 1e8).toFixed(1) + '亿' : Math.round(v / 1e4) + '万';
      head += `【封单最强】${seal.map(x => `${x.name} ${inf(x.sealAmount)}`).join('、')}\n`;
    }
    return head;
  } catch { return ''; }
}

// ── 学习日报：每日22点推送当日学习成果 ──────────────────────────────────────
// 用户原话：「当日学习了啥列个大纲，每天22点前通过私密通道发我」
// 内容：K线补齐统计、学习库规模、命中率变化、各策略表现、学习进化自检
function buildLearnReport() {
  const ds = todayStr();
  const _fmt = d => `${d.slice(0, 4)}-${d.slice(4, 6)}-${d.slice(6, 8)}`;
  // K线补齐统计（取今日进度）
  const kbf = _kbfProg || {};
  const kbfToday = kbf.day === ds ? kbf : { scanned: 0, added: 0, fail: 0 };
  let klineTotal = 0;
  try { klineTotal = fs.readdirSync(KLINE_CACHE).filter(f => /^\d{6}\.json$/.test(f)).length; } catch {}
  const totalStocks = (S.stocks || []).length;
  const coverage = totalStocks ? Math.round(klineTotal / totalStocks * 100) : 0;
  // 学习库规模
  const la = laDb() || {};
  const zp = zpDb() || {};
  // 命中率统计（全部信号·分档，样本≥5才展示）
  const emp = empTable();
  const bucketRows = [];
  for (const b of EMP_BUCKETS) {
    const v = emp[`全部|${b}`];
    if (v && v.n >= 5) bucketRows.push(`${b}档${v.rate}%(${v.n})`);
  }
  // 各策略表现
  const bm = bigMoneyStats();
  const sim = similarStats();
  const trend = trendStats();   // ⛔ 2026-10-28 修：原读 S.learn.trend（无人写入的死字段），改就地统计
  // 融合进化
  const fused = learnFusedReport();
  let m = `═══ 🧠 学习日报 · ${_fmt(ds)} ═══\n`;
  m += `📊 K线补齐：今日扫描 ${kbfToday.scanned || 0} 只 · 补齐 ${kbfToday.added || 0} 只 · 失败 ${kbfToday.fail || 0} 只\n`;
  m += `   磁盘缓存 ${klineTotal} 只 / 全市场 ${totalStocks} 只（覆盖率 ${coverage}%）\n`;
  m += `\n📚 学习库规模\n`;
  m += `   全A走势学习：${la.n || 0} 条样本 · 基准涨≥3% ${la.base ? (la.base * 100).toFixed(1) : '-'}% · 封板 ${la.baseZt ? (la.baseZt * 100).toFixed(1) : '-'}%\n`;
  m += `   涨停前形态：${zp.n || 0} 条样本 · 次日封板基准 ${zp.baseZt ? (zp.baseZt * 100).toFixed(1) : '-'}%\n`;
  if (bucketRows.length) {
    m += `\n🎯 实测命中率（全部信号·分档）\n   ${bucketRows.join(' · ')}\n`;
  }
  if (bm && bm.n >= 5) {
    m += `\n💰 大单策略：近${bm.n}条·跨${bm.days}日 · 涨停率${bm.luRate}% · 命中率${bm.hitRate}%\n`;
  }
  if (sim && sim.n >= 5) {
    m += `🔄 相似策略：近${sim.n}条·跨${sim.days}日 · 涨停率${sim.luRate}% · 命中率${sim.hitRate}%\n`;
  }
  if (trend && trend.n >= 5) {
    m += `📈 趋势策略：近${trend.n}条·跨${trend.days}日 · 涨停率${trend.luRate}% · 命中率${trend.hitRate}%\n`;
  }
  if (fused && fused.fusedN) {
    const ok = fused.rows.filter(x => x.lift != null);
    if (ok.length) {
      const avg = Math.round(ok.reduce((s, x) => s + x.lift, 0) / ok.length);
      m += `\n🧬 学习进化：平均${avg >= 0 ? '+' : ''}${avg}pp（${ok.length}档可比较）\n`;
    }
  }
  m += `\n📋 当日学习动作\n`;
  m += `   · 信号回验：每10分钟一轮，记录历史事件频率与研究排序\n`;
  m += `   · 全A入库：15:40后自动执行（learnall + ztpre）\n`;
  m += `   · K线补齐：15:30后进入极速模式（30秒/2000只）\n`;
  m += `   · 自适应调参：大单/相似/趋势三处闭环自动优化门槛\n`;
  return m;
}
function pushLearnReport() {
  const ds = todayStr();
  if (sentToday(learnReportSentDate, ds, /学习日报/, 21 * 60 + 55)) return;   // gn 轮：补 dueMin，收盘后被拉起的容器也能补发（必达）
  const msg = buildLearnReport();
  if (pushAll(msg, true, { private: true }) !== false) learnReportSentDate = ds;
}

// ── 推送结果学习日报（2026-10-30）────────────────────────────────────────
// 数据源：daily-brief/_all_outcomes_report_<ds>.json（_analyze_all_outcomes.js 收盘后生成，实测 16:43-16:49）。
// 内容：今日推送 outcome 分布 + 上涨率 TOP 信号 + 涨/跌分水岭条件 + 涨停 vs  mere涨区分。
function buildOutcomesReport() {
  const ds = todayStr();
  const _fmt = d => `${d.slice(0, 4)}-${d.slice(4, 6)}-${d.slice(6, 8)}`;
  const fp = path.join(__dirname, '..', 'stock-dashboard-artifacts', 'daily-brief', `_all_outcomes_report_${ds}.json`);
  if (!fs.existsSync(fp)) return null;
  let r;
  try { r = JSON.parse(fs.readFileSync(fp, 'utf8')); } catch { return null; }
  if (!r || !r.summary || !r.summary.total) return null;
  const s = r.summary;
  const pct = n => (n / s.total * 100).toFixed(1) + '%';
  let m = `═══ 📈 推送结果学习日报 · ${_fmt(ds)} ═══\n`;
  m += `推送 ${s.total} 只：涨停 ${s.zt}（${pct(s.zt)}）｜上涨 ${s.up}（${pct(s.up)}）｜下跌 ${s.down}（${pct(s.down)}）｜平盘 ${s.flat}\n`;
  m += `整体上涨率 ${s.winRate}%（含涨停）\n`;
  // 上涨率 TOP 信号（样本≥3，按样本量排序取前 5）
  const top = (r.titleStats || []).filter(x => x.n >= 3).sort((a, b) => b.n - a.n).slice(0, 5);
  if (top.length) {
    m += `\n【上涨率 TOP 信号】\n`;
    for (const x of top) {
      const title = String(x.title).replace(/═/g, '').trim();
      m += `${x.winRate}%  ${title}（${x.n}条`;
      if (x.ztRate > 0) m += `·涨停率${x.ztRate}%`;
      m += `）\n`;
    }
  }
  // 涨 vs 跌 分水岭（topDiffs 前 4，翻译成中文条件名）
  const FEAT_CN = { amp20: '20日振幅', dd60: '60日回撤', pct: '推送时涨幅', gap20: '20日缺口数', gap: '当日跳空', cum5: '5日累计涨幅', amt: '成交额', upCons: '连涨天数', zt20: '20日涨停次数', zt60: '60日涨停次数', vr: '量比', rangePos: '区间位置', volTrend: '量能趋势', runUp: '60日涨幅' };
  const td = (r.topDiffs || []).slice(0, 4);
  if (td.length) {
    m += `\n【涨 vs 跌 分水岭】\n`;
    for (const d of td) {
      const cn = FEAT_CN[d.key] || d.key;
      m += `${cn}：涨中位 ${d.upMedian} / 跌中位 ${d.downMedian}（${d.direction}）\n`;
    }
    m += `规律：${td.filter(d => d.direction === 'down更高').map(d => FEAT_CN[d.key] || d.key).join('、') || '—'}偏大的是易跌票（追高被套特征）；${td.filter(d => d.direction === 'up更高').map(d => FEAT_CN[d.key] || d.key).join('、') || '—'}占优的是易涨票\n`;
  }
  // 涨停 vs  mere涨
  const zu = (r.ztUpDiffs || []).slice(0, 3);
  if (zu.length) {
    m += `\n【涨停 vs mere 涨】\n`;
    for (const d of zu) {
      const cn = FEAT_CN[d.key] || d.key;
      m += `${cn}：涨停 ${d.ztMedian} / 仅涨 ${d.upMedian}（${d.direction}）\n`;
    }
  }
  m += `\n完整报告：面板「推送流水」或 all-outcomes-${ds.slice(0,4)}-${ds.slice(4,6)}-${ds.slice(6,8)}.html`;
  return m;
}
function pushOutcomesReport() {
  const ds = todayStr();
  if (sentToday(outcomesReportSentDate, ds, /推送结果学习日报/, 16 * 60 + 30)) return;   // 收盘后任何时刻补发窗口
  const msg = buildOutcomesReport();
  if (!msg) return;   // 报告未生成（analyze 未跑）——下轮再试
  if (pushAll(msg, true, { private: true }) !== false) outcomesReportSentDate = ds;
}

