    if ((s.amount || 0) < 1.5e8) continue;
    // ly：加速度档——秒封票没有 +3~6.5% 稳态（几秒拉穿），涨速>2%/分 直接放行不等稳态
    const _fast = (s.speed || 0) > 2;
    if (!_fast && (s.speed || 0) <= 0) continue;
    if (A.isLimitUp(s.code, s.name, pct)) continue;
    if (!_fast && !((s.mainPct || 0) > 0.3 || (s.mainInflow || 0) > 0 || (s.superNet || 0) > 0 || (s.bigNet || 0) > 0)) continue;   // lr：资金条件放宽；ly：加速度档免资金条件（秒封窗口来不及验证资金）
