function classifyNews(raw, nameOf) { return classifyNewsRows(raw,nameOf,false); }
function classifyNewsRows(raw, nameOf, neutralOnly) {
  const out = [];
  for (const n of raw) {
    if (!n || typeof n.title !== 'string' || (n.summary != null && typeof n.summary !== 'string')) continue;
    const title = n.title, body = n.summary || '', summary = body.slice(0,90);
    const assessment = require('./src/core/news-sentiment').assessNews(title,body);
    if ((assessment.type === 'neutral') !== neutralOnly) continue;
    const codes = [...new Set((Array.isArray(n.stockList)?n.stockList:[]).map(sl=>/^([013])\.(\d{6})$/.exec(String(sl))?.[2]).filter(Boolean))];
    if (neutralOnly && !codes.length) continue;
    const text = title + '\n' + body;
    const sectors = [...new Set((S.sectors||[]).filter(s=>s.name&&s.name.length>=2&&text.includes(s.name)).map(s=>s.name))].slice(0,2);
    out.push({id:n.code,t:n.showTime||'',...newsPublicationMetadata(n),title,summary,codes,
      stocks:codes.map(c=>`${nameOf.get(c)||''}(${c})`),type:assessment.type,why:assessment.why,assessment,sectors});
  }
  return out;
}
function classifyNeutral(raw, nameOf) { return classifyNewsRows(raw,nameOf,true); }
function mergeArchive(list, items, keepAll) { // 按 id 去重合并 → （keepAll 时不过滤近3日）→ 时间倒序 → 上限400/假期缓冲上限
  // These lists are current projections. The append-only journal retains every
  // original and revision; a prior category cannot survive a changed version.
  const current=new Map(list.map(x=>[String(x.id),x]));
  for(const it of items)if(newsEvidenceAllowsItem(it))current.set(String(it.id),it);
  const arr=[...current.values()].filter(x=>newsEvidenceAllowsItem(x)&&(keepAll||within3Days(x.t)));
  return arr.sort((a, b) => (a.t < b.t ? 1 : -1)).slice(0, keepAll ? HOLIDAY_BUF_CAP : NEWS_ARCHIVE_CAP);
}
async function fetchNewsPage(column, sortEnd, size) {
  const u = `https://np-weblist.eastmoney.com/comm/web/getFastNewsList?client=web&biz=web_724&fastColumn=${column}&sortEnd=${encodeURIComponent(sortEnd || '')}&pageSize=${size}&req_trace=${Date.now()}${column}${Math.floor(Math.random() * 999)}`;
  const r = await em.get(u, 8000);
  return r && r.data ? r : null;
}
// 启动播种：向回翻页抓取近3日快讯（每栏目3页×100条），分类后入归档
async function seedNews() {
  try {
    const raw = [];
    for (const col of [101, 104]) {
      let sortEnd = '';
      const seenCursors = new Set();
      for (let page = 0; page < 3; page++) {
        try {
          const r = await fetchNewsPage(col, sortEnd, 100);
          const rows = r?.data?.fastNewsList;
          if (!Array.isArray(rows) || !rows.length) break;
          raw.push(...rows);
          const next = r.data.sortEnd;
          if (!next || seenCursors.has(String(next))) break;
          seenCursors.add(String(next)); sortEnd = next;
          if (page < 2) await em.delay(400);
        } catch { console.warn(`[news] 播种栏目 ${col} 暂不可用，保留已取得页面`); break; }
      }
    }
    if (!raw.length) return;
    captureNewsEvidence(raw);
    const nameOf = new Map(S.stocks.map(s => [s.code, s.name]));
    const items = classifyNews(raw, nameOf);
    const neutral = classifyNeutral(raw.filter(n => !items.some(x => x.id === n.code)), nameOf);
    S.news.badAll = mergeArchive(S.news.badAll, items.filter(x => x.type === 'bad'));
    S.news.goodAll = mergeArchive(S.news.goodAll, items.filter(x => x.type === 'good'));
    S.news.neutralAll = mergeArchive(S.news.neutralAll, neutral);
    // 假期缓冲：休市期把全部新闻（不过滤近3日）累积进 holidayBuf，供「开盘前夜汇总」覆盖整个假期；交易日则清空
    if (isTradeDay(require('./src/core/news-china-clock').newsChinaClock())) S.news.holidayBuf = [];
    else S.news.holidayBuf = mergeArchive(S.news.holidayBuf || [], items.concat(neutral), true);
    if (!S.news.baseline) { for (const x of S.news.goodAll) S.news.goodPushed.add(x.id); S.news.baseline = true; }
    S.news.time = new Date().toLocaleTimeString('zh-CN');
    // 播种后同样预取板块关联成分股（启动时 S.sectors 可能未就绪则跳过，后续刷新自动补）
    // ⛔ 2026-10-06：它是 async，不 await 时外层 try/catch 抓不到 reject（只会变 unhandledRejection），
    //   必须自己接住。这里是「异步不阻塞」的预取，失败不影响主流程，明确吞掉即可。
    ensureSectorStocks([...new Set([...S.news.goodAll.slice(0, 30), ...S.news.badAll.slice(0, 30)].flatMap(x => x.sectors || []))]).catch(() => {});
    saveNews();
    console.log(`[news] 3日播种完成: 利空${S.news.badAll.length} 利好${S.news.goodAll.length} 中性${S.news.neutralAll.length}`);
  } catch (e) { console.error('[news] seed', e.message); }
}
// 增量刷新：拉最新两栏目各100条，分类合并入3日归档；新利好(带A股码)聚合推送
async function refreshNews() {
  try {
    const rs = await Promise.allSettled([fetchNewsPage(101, '', 100), fetchNewsPage(104, '', 100)]);
    const raw = [];
    const complete=rs.length===2&&rs.every(r=>r.status==='fulfilled'&&Array.isArray(r.value?.data?.fastNewsList));
    for (const r of rs) if (r.status === 'fulfilled' && Array.isArray(r.value?.data?.fastNewsList)) raw.push(...r.value.data.fastNewsList);
    S.news.riskSnapshot={status:'unknown',checkedAt:Date.now(),source:'eastmoney-fast-news',columnsComplete:complete};
    captureNewsEvidence(raw);
    // Preserve successful evidence during partial outages, while holding recommendations.
    if(complete&&S.news.evidenceIntake?.status!=='unknown'&&!(S.news.evidenceIntake?.rejected>0))
      S.news.riskSnapshot={status:'available',checkedAt:Date.now(),source:'eastmoney-fast-news',columnsComplete:true};
    if (!raw.length) return;
    const nameOf = new Map(S.stocks.map(s => [s.code, s.name]));
    const items = classifyNews(raw, nameOf);
    const neutral = classifyNeutral(raw.filter(n => !items.some(x => x.id === n.code)), nameOf);
    S.news.badAll = mergeArchive(S.news.badAll, items.filter(x => x.type === 'bad'));
    S.news.goodAll = mergeArchive(S.news.goodAll, items.filter(x => x.type === 'good'));
    S.news.neutralAll = mergeArchive(S.news.neutralAll, neutral);
    // 假期缓冲累积（休市时）/ 交易日清空：让「开盘前夜汇总」能拿到整个长假的完整新闻
    if (isTradeDay(require('./src/core/news-china-clock').newsChinaClock())) S.news.holidayBuf = [];
    else S.news.holidayBuf = mergeArchive(S.news.holidayBuf || [], items.concat(neutral), true);
    S.news.bad = S.news.badAll.slice(0, 40);
    S.news.good = S.news.goodAll.slice(0, 40);
    S.news.badCodes = new Set(S.news.badAll.flatMap(x => x.codes));
    S.news.goodCodes = new Set(S.news.goodAll.flatMap(x => x.codes)); // 利好关联股（推送门槛降低=加推）
    S.news.badSectors = new Set(S.news.badAll.flatMap(x => x.sectors));
    S.news.time = new Date().toLocaleTimeString('zh-CN');
    // 利好消息推送：新出现且带A股代码的利好聚合推送（每条只推一次）
    const freshGood = S.news.riskSnapshot.status==='available' ? S.news.goodAll.filter(x => x.codes.length && !S.news.goodPushed.has(x.id) && newsDecisionAllowsItem(x)) : [];
    // 非开盘时段：利好只更新面板与归档，不做即时推送（新闻是主要噪音源），
    // 统一留给每日新闻汇总（21:00）/ 周末汇总（周日21:00）一起发。
    // 标记仍照打，避免次日开盘一次性补推一大堆。
    const newsSession = isTradingTime();
    if (freshGood.length && !newsSession) {
      for (const x of freshGood) S.news.goodPushed.add(x.id);
      console.log(`[news] 非开盘时段：${freshGood.length}条新利好仅入面板，不做即时推送`);
    }
    if (freshGood.length && newsSession) {
      for (const x of freshGood) S.news.goodPushed.add(x.id);
      const list = freshGood.slice(0, 8);
      pushAll('═══ 📰 利好消息·关联个股 ═══\n' + list.map(x => {
        // 板块间接影响个股：新闻提到的板块成分股Top4（缓存有则显示）
        const ind = [];
        for (const nm of (x.sectors || [])) {
          const c = S.secStocks && S.secStocks.get(nm);
          if (!c || !c.list) continue;
          for (const s of c.list) {
            if (x.codes.includes(s.code) || ind.some(i => i.code === s.code) || A.isJunkName(s.name)) continue;
            ind.push(s);
            if (ind.length >= 4) break;
          }
          if (ind.length >= 4) break;
        }
        return `▪ ${x.title}\n  关联: ${x.codes.map(c => (nameOf.get(c) || '') + '(' + c + ')').join('、')}\n  选股逻辑: ${x.why || '消息面利好'}` +
          `${ind.length ? `\n  板块间接影响(${x.sectors.join('/')}): ${ind.map(s => `${s.name} ${s.pct > 0 ? '+' : ''}${s.pct}%`).join('、')}` : ''}` +
          `${x.summary ? '\n  摘要: ' + x.summary : ''}`;
      }).join('\n') + (freshGood.length > 8 ? `\n…另有${freshGood.length - 8}条见面板` : ''));
    }
    // 板块间接关联个股预取：利好+利空归档里出现过的板块（异步不阻塞，30分钟缓存）
    const secNames = [...new Set([...S.news.goodAll.slice(0, 30), ...S.news.badAll.slice(0, 30)].flatMap(x => x.sectors || []))];
    ensureSectorStocks(secNames).catch(() => {});   // 同上：async 不 await，reject 进不了外层 catch
    saveNews();
    console.log(`[news] 刷新: 3日归档 利空${S.news.badAll.length} 利好${S.news.goodAll.length} 中性${S.news.neutralAll.length}, 本轮新利好推送${Math.min(freshGood.length, 8)}条`);
  } catch (e) { S.news.riskSnapshot={status:'unknown',checkedAt:Date.now(),source:'eastmoney-fast-news',columnsComplete:false};console.error('[news]', e.message); }
}

// 每日新闻汇总（工作日21:00推送 / 周日21:00周末汇总）：利好/利空分析归类 + 受益/受累板块个股 + 模拟盘避险
// dates: 'YYYY-MM-DD' 数组（要汇总哪些天）；label: 推送标题；topN: 每类条数
function buildNewsDigest(dates, label, topN, src) {
  topN = topN || 5;
  const title = label || '每日新闻汇总';
  // src：注入自定义数据源（假期全景汇总用 holidayBuf 拆出的 bad/good/neutral + arcLabel），不传则用近3日归档
  const badAll = (src && src.bad) || S.news.badAll;
  const goodAll = (src && src.good) || S.news.goodAll;
  const neutralAll = (src && src.neutral) || S.news.neutralAll;
  const inDays = list => list.filter(x => newsEvidenceAllowsItem(x) && dates.includes((x.t || '').slice(0, 10)));
  const bad = inDays(badAll), good = inDays(goodAll), neutral = inDays(neutralAll);
  const freq = (list, key) => { const m = {}; for (const it of list) for (const s of (it[key] || [])) m[s] = (m[s] || 0) + 1; return Object.entries(m).sort((a, b) => b[1] - a[1]); };
  const arcLabel = (src && src.arcLabel) || `近3日归档: 利空${S.news.badAll.length}/利好${S.news.goodAll.length}/中性${S.news.neutralAll.length}`;
  let msg = `═══ 📰 ${title} · ${dates.join('/')} ═══\n归类结果: 利空 ${bad.length} 条 · 利好 ${good.length} 条 · 中性 ${neutral.length} 条\n（${arcLabel}）`;
  const badSecs = freq(bad, 'sectors').slice(0, 5), goodSecs = freq(good, 'sectors').slice(0, 5);
  if (bad.length) {
    msg += '\n\n【⚠️ 利空焦点】\n' + bad.slice(0, topN).map(x => `▪ ${x.title.slice(0, 34)}\n  关联: ${(x.stocks || []).slice(0, 3).join('、') || '板块性利空'} | ${(x.why || '').slice(0, 26)}`).join('\n');
    if (badSecs.length) msg += '\n  受累板块: ' + badSecs.map(([s, n]) => `${s}(${n}条)`).join(' ');
  } else msg += '\n\n【⚠️ 利空焦点】期间无命中利空关键词的新闻';
  if (good.length) {
    msg += '\n\n【✅ 利好焦点】\n' + good.slice(0, topN).map(x => `▪ ${x.title.slice(0, 34)}\n  关联: ${(x.stocks || []).slice(0, 3).join('、') || '板块性利好'} | ${(x.why || '').slice(0, 26)}`).join('\n');
    if (goodSecs.length) msg += '\n  受益板块: ' + goodSecs.map(([s, n]) => `${s}(${n}条)`).join(' ');
  } else msg += '\n\n【✅ 利好焦点】期间无命中利好关键词的新闻';
  if (dates.length > 1) { // 周末汇总：额外给出高频受益/受累个股排行
    const gs = freq(good, 'stocks').slice(0, 6), bs = freq(bad, 'stocks').slice(0, 4);
    if (gs.length) msg += '\n\n【🔥 周末高频受益个股】\n' + gs.map(([s, n]) => `▪ ${s}（${n}条利好）`).join('\n');
    if (bs.length) msg += '\n【⛔ 周末避雷个股】\n' + bs.map(([s, n]) => `▪ ${s}（${n}条利空）`).join('\n');
  }
  const badCodes = new Set(badAll.filter(newsDecisionAllowsItem).flatMap(x => x.codes));
  const warn = [];
  for (const [acc, cfg] of Object.entries(PAPER_CFG)) {
    const hit = Object.values(PAPER[acc].positions || {}).filter(p => badCodes.has(p.code));
    if (hit.length) warn.push(`${cfg.name}: ${hit.map(p => `${p.name}(${p.code})`).join('、')} ⚠️持仓踩利空`);
  }
  if (warn.length) msg += '\n\n【🛡 模拟盘避险】\n' + warn.join('\n');
  else msg += '\n\n【🛡 模拟盘避险】当前持仓无利空标的，新进候选已自动避开利空股';
  msg += `\n\n完整清单见面板 · 汇总时间 ${new Date().toLocaleTimeString('zh-CN')}`;
  return msg;
}

// 假期辅助函数（开盘前夜汇总用）
function fmtD8(d) { return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`; }
// 假期跨度：从今天往回数，直到遇到一个交易日为止（不含该交易日），返回 ['YYYY-MM-DD', ...]（今天在前）
// isTD 可注入用于单测；默认走真实 isTradeDay
function holidaySpanUpToToday(isTD) {
  const f = isTD || isTradeDay;
  const out = [];
  for (let i = 0; i < 40; i++) {
    const d = new Date(Date.now() - i * 86400000);
    if (f(d)) break;
    out.push(fmtD8(d));
  }
  return out;
}
// 假期开盘前汇总是否应触发：今天休市 + 明天开盘 + 跨度≥3天(排除普通周末) + 缓冲非空
function holidayDigestShouldFire(bufLen, isTD) {
  const f = isTD || isTradeDay;
  const now = new Date();
  if (f(now)) return { fire: false, span: [], reason: 'today-trade-day' };
  if (!f(new Date(Date.now() + 86400000))) return { fire: false, span: [], reason: 'tomorrow-not-open' };
  const span = holidaySpanUpToToday(f);
  if (span.length < 3) return { fire: false, span, reason: 'span<3-normal-weekend' };
  if (!bufLen) return { fire: false, span, reason: 'empty-buffer' };
  return { fire: true, span, reason: 'ok' };
}
// __HOLIDAY_HELPERS_END__

// 每日新闻汇总「今天是否已送达」标记。
