let digestMorningSentDate = sentLockFromPushLog(/盘面摘要 · 早盘/, '盘面摘要·早盘');
let digestNoonSentDate = sentLockFromPushLog(/盘面摘要 · 午盘/, '盘面摘要·午盘');
