function sseSendEdit(evt, data) { _write(SSE_EDIT, evt, data); }

// ---------------- 我的持仓：录入 / 盯盘 / 风控加减仓 ----------------
// 依赖在 SSE 与 pushAll 都已就绪后注入（pushAll 定义在下方，此处取函数引用会提升，安全）
// privReady 注入：持仓模块据此决定推送里要不要写金额（私密机器人已配 → 写；否则抹掉）
// isReplica 注入给持仓模块：清空这类"最重操作"的提醒【只由线上实例发】，
// 副本那一份必须闭嘴（2026-10-06：副本连发导致手机一次操作收到两条）。
const HD = createHoldings({ fs, path, dir: __dirname, S, em, sseSend, sseSendEdit, pushAll, privReady, isReplica, dataWindow: isDataWindow });
// ⛔ lc 轮（2026-10-27）：上一行 dataWindow 注入是风控"盘外不推送"闸的唯一开关 —— la/lb 发布时
//    并行会话没带上这行，线上只有落盘去重、没有数据窗口闸（holdings.js 里 _inDataWindow 恒放行），
//    凌晨每 30 分钟重弹照旧。删这行 = 闸永久失效，守门 _test_holdings_watch_gate 只能测模块、测不到注入。
// 后台重算并实时推送：写操作不再让用户等着行情接口返回（删除/改仓位的卡顿感从这里根治）
// ⚠️ 2026-10-06 从请求处理函数内部提到顶层：线上→本地回拉对账（pullHoldingsDownstream）
//    在定时器里也要广播，作用域够不着就会 ReferenceError —— 而 node --check 查不出来。
function kick() {
  // ① 先"秒推"：数据此刻已落盘，让所有端立刻回取最新列表——不等行情重算。
  //    这一条是根治「手机改完电脑没反应 / 电脑改完手机没反应」的关键：
  //    以前必须先等行情重算完才广播，重算要拉行情，慢的时候要好几秒。
  sseSendEdit('holding', { changed: true, ts: Date.now() });
  // ② 再后台重算估值与预警，算完把带结果的那份再推一次（用于抬头预警提示）
  setTimeout(() => {
    HD.compute(true).then(r => {
      sseSendEdit('holding', {
        time: r.time, level: r.level,
        items: r.items.map(i => ({ code: i.code, name: i.name, level: i.level, acts: (i.acts || []).map(a => a.type), tags: i.tags || [], locked: !!i.locked }))
      });
    }).catch(() => {});
  }, 0);
}

// ---------------- 6 位授权码登录：给"粘贴不了密码"的设备一条不用粘贴的路 ----------------
// ⚠️ 必须放在模块顶层！旧版把 AUTH_CODES 写在 createServer 的回调里，等于每个 HTTP 请求
//    都重建一次 Map：生成请求一返回码就没了，另一台设备来兑换时必然查不到 → 一直提示
//    「授权码无效」。挪到这里之后，码在进程生命周期内一直有效（10 分钟内）。
const AUTH_CODES = new Map();   // code -> { role, exp, by, name }
function _genCode() {
  for (let i = 0; i < 50; i++) {
    const c = String(crypto.randomInt(100000, 1000000));
    if (!AUTH_CODES.has(c)) return c;
  }
  return String(Date.now()).slice(-6);
}
function _sweepCodes() {
  const now = Date.now();
  for (const [c, v] of AUTH_CODES) if (v.exp < now) AUTH_CODES.delete(c);
}
// 设备台账按 IP 归类：同一个 IP = 同一台电脑/同一个网络出口，统一折叠成一组，
// 组内按最近活跃排序，前台只渲染组标题（默认收起），解决「IP 栏显示太多」。
function groupByIp(items) {
  const m = new Map();
  for (const it of items || []) {
    const k = String((it && it.ip) || '').trim() || '未知 IP';
    if (!m.has(k)) m.set(k, []);
    m.get(k).push(it);
  }
  return [...m.entries()].map(([ip, list]) => {
    list.sort((a, b) => (b.ts || 0) - (a.ts || 0));
    return {
      ip, n: list.length,
      edit: list.filter(x => x.role === 'edit').length,
      view: list.filter(x => x.role === 'view').length,
      last: Math.max(0, ...list.map(x => x.ts || 0)),
      names: [...new Set(list.map(x => x.name || '未命名设备'))].slice(0, 3),
      items: list
    };
  }).sort((a, b) => b.last - a.last);
}

// ── u 版 H1：跨站请求拦截（CSRF 根治）────────────────────────────────────
// 旧版两个问题叠加：① 所有响应都带 ACAO:*；② 本机请求恒为管理员。
// 于是用户浏览器里任何一个恶意网页都能用 text/plain 简单请求打本机 API
// （包括在线改源码的接口），服务端看到 127.0.0.1 就放行 → 远程执行。
// 规则：浏览器跨站请求必带 Origin/Referer，其主机名必须与 Host / X-Forwarded-Host
//       一致（即同源）；不一致的 /api/ 请求直接 403。非浏览器客户端（curl/urllib，
//       不带 Origin）不受影响；CORS 头也只对同源 Origin 反射，不再 *。
function _hostOnly(h) { return String(h || '').split(':')[0].toLowerCase(); }
function sameOriginOk(req) {
  const srcs = [req.headers.origin, req.headers.referer].filter(Boolean);
  if (!srcs.length) return true;   // 非浏览器/直接输入网址：无来源头，放行
  const allow = new Set([_hostOnly(req.headers.host), _hostOnly(req.headers['x-forwarded-host'])].filter(Boolean));
  // 生产域名固定放行：云端反代的 Host/X-Forwarded-Host 写法再变，面板自己的同源请求也不会被误伤
  try { allow.add(_hostOnly(new URL(process.env.QD_PUBLIC_URL || 'https://quant-dashboard-77614.app.workbuddy.host/').host)); } catch {}
  for (const o of srcs) {
    if (String(o).toLowerCase() === 'null') return false;   // file:// 或沙箱 iframe：拒
    try { if (!allow.has(_hostOnly(new URL(o).host))) return false; } catch { return false; }
  }
  return true;
}

// ── v 版：区分「手动触发」与「定时任务」的推送上下文 ──────────────────────
// 场景：用户在本地面板点「立即巡检 / 手动推送」，副本实例却把它拦了 → 手机上毫无动静，
//       看起来就像推送坏了。但定时任务若也照发，线上和本地会同时推，手机一次来两份。
// 做法：用 AsyncLocalStorage 标记「这次调用链源自一个 HTTP 请求」——
//       手动操作都在请求处理里（含其异步延续），定时任务跑在 setInterval 里没有这个上下文。
const { createDashboardServer } = require('./src/server/bootstrap');
const _httpBootstrap = createDashboardServer({
  handle,
  sameOriginOk,
  bodyLimit: BODY_LIMIT,
  port: PORT,
  host: HOST,
  onListen: () => {
    console.log(`量化看盘平台: http://127.0.0.1:${PORT}`);
    // Local recovery is part of every boot, including offline smoke; only collectors are skipped.
    loadSnapshotsOnBoot();
    // 仅隔离集成测试使用：跳过外部行情拉取、推送和定时任务，真实启动仍执行 init()。
    if (process.env.V6_ISOLATED_BOOT_SMOKE !== '1') {
      init().catch(e => console.error('[init]', e));
      try{getStockObservationMonitor()?.start();}catch{console.error('[research-observation] 采集队列未启动');}
    }
  }
});
const inManualPush = _httpBootstrap.inManualPush;
_httpBootstrap.server.on('error', e => {
  if (e.code === 'EADDRINUSE') { console.log('[init] 8787 端口已有实例运行，本实例退出'); process.exit(0); }
  throw e;
});


// ---------------- 开发者锁：改源码/改配置/清盘前必须验证密码 ----------------
// 密码只用 scrypt 派生 + 加盐哈希保存在 access.json，绝不存明文；校验用 timingSafeEqual 防时序探测
const ACCESS_FILE = path.join(__dirname, 'access.json');
const crypto = require('crypto');
let accessSecret = null; // {salt, hash, devices:{摘要->{name,ip,at}}}
try {
  const a = JSON.parse(fs.readFileSync(ACCESS_FILE, 'utf8'));
  if (a && a.salt && a.hash) { accessSecret = a; accessSecret.devices = accessSecret.devices || {}; }
} catch {}
