// 落盘 + 只推私密通道。返回 { ok, sent, url }
async function srcPkgShip(b64, ver, name) {
  let buf = null;
  try { buf = Buffer.from(String(b64 || ''), 'base64'); }
  catch (e) { return { ok: false, error: 'base64 解码失败' }; }
  if (!buf || buf.length < 1024) return { ok: false, error: '源码包为空或过小' };
  if (buf.length > 40 * 1024 * 1024) return { ok: false, error: '源码包过大（>40MB）' };
  if (buf.slice(0, 2).toString('latin1') !== 'PK') return { ok: false, error: '不是有效的 zip 包' };
  try { fs.mkdirSync(SRCPKG_DIR, { recursive: true }); } catch (e) {}
  const token = crypto.randomBytes(18).toString('hex');
  const fn = 'srcpkg-' + String(ver || 'x').replace(/[^\w.-]/g, '') + '-' + token.slice(0, 8) + '.zip';
  try { fs.writeFileSync(path.join(SRCPKG_DIR, fn), buf); }
  catch (e) { return { ok: false, error: '写入失败：' + ((e && e.message) || e) }; }
  // 只留最近 3 个包：线上实例可能被回收/回退，堆一堆旧包毫无意义
  try {
    const olds = fs.readdirSync(SRCPKG_DIR).filter(x => /^srcpkg-.*\.zip$/.test(x))
      .map(x => { try { return { x, t: fs.statSync(path.join(SRCPKG_DIR, x)).mtimeMs || 0 }; } catch (e) { return { x, t: 0 }; } })
      .sort((a, b) => b.t - a.t).slice(3);
    for (const o of olds) { try { fs.unlinkSync(path.join(SRCPKG_DIR, o.x)); } catch (e) {} }
  } catch (e) {}
  const v = { ver: String(ver || ''), name: String(name || ('源码_' + ver + '.zip')), fn, token, size: buf.length, time: new Date().toLocaleString('zh-CN') };
  _srcPkg = v;
  const card = srcPkgCard(v);
  if (!privReady()) {
    // ⛔ 没有私密机器人就绝不外发：宁可让你去面板看，也不把源码链接丢进群里
    pushLog('🚫 源码包未外发', card, { channel: '飞书·私密', note: '未配置私密机器人 → 按红线不往群里发源码包链接' });
    return { ok: true, sent: false, url: srcPkgUrl(token), note: '未配置私密通道，链接未外发（红线：源码包不发群）' };
  }
  // ⛔ 2026-10-07 修（本轮角度：不看代码看事实 —— 从线上真实运行数据反查）：
  //    线上推送流水最近 30 条里 **25 条是「📦 源码包 · 仅本人可见」** —— 一天发十几个版本，
  //    就往手机弹十几条源码包。"私密通道同步发源码"是用户点名要的能力，必须保留，
  //    但**每发一版弹一条**显然不是他要的频次：它既刷屏，又和行情推送抢同一个"少而精"额度。
  //    现在同一天只推一次 —— 能力一点没少（链接照样生成、照样进面板「推送流水」，随时能取），
  //    只是不再重复弹手机。判据复用 bt 轮那套 pushedToday（认落盘流水、跨重启可查，
  //    且只认真实送达：被闸门拦下的不算推过，下轮照样补）。
  if (pushedToday(/源码包/)) {
    pushLog('🚫 源码包当日已推过', card, { channel: '飞书·私密', note: '同一天只推一次，避免每发一版弹一条；链接在面板「推送流水」里照样能取' });
    return { ok: true, sent: false, url: srcPkgUrl(token), note: '今天已经推过源码包了，本次只记流水不外发（链接见面板「📋 推送流水」）' };
  }
  // ⛔ 副本闸（2026-10-28 推送模块补）：源码包链接含 token，副本实例一律不外发。
  //    本函数绕过 pushAll 直连私密通道（L16565 直接 feishuProbe），因此 pushAll 内置的
  //    副本闸管不到它 —— 必须自己补一道，与 L6581「副本只同步、不主动外发」同语义：
  //    只记流水、绝不发送；链接照样生成、照样进面板「推送流水」，主实例行为零变化。
  if (isReplica()) {
    pushLog('副本拦截(不外发)', card, { channel: '飞书·私密', note: '副本只同步不主动外发：源码包链接（含 token）仅限主实例推送，面板「推送流水」可查' });
    return { ok: true, sent: false, url: srcPkgUrl(token), note: '副本实例不外发源码包（链接见面板「📋 推送流水」）' };
  }
  const r = await feishuProbe(feishuSecId(), process.env.V6_FEISHU_PRIVATE_SECRET || (S.config && S.config.feishuSecSecret) || '', card);
  if (r && r.ok) {
    pushLog('✅ 已送达(私密)', card, { channel: '飞书·私密', note: '源码包链接仅本人可见：' + feishuSecMask() });
    return { ok: true, sent: true, url: srcPkgUrl(token) };
  }
  pushLog('❌ 源码包发送失败', card, { channel: '飞书·私密', error: (r && r.msg) || '' });
  return { ok: true, sent: false, url: srcPkgUrl(token), error: '私密机器人发送失败：' + ((r && r.msg) || '未知') };
}
